export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-math-fontfamily":{"intro":"This lab will guide you through the process of changing the family of fonts for each individual text element in a plot using the Python Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries. We will be using Matplotlib to create the plot and to manipulate the text elements."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create the Plot","body":["Now, we will create a simple plot for the background using the plot() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(6, 5))\nax.plot(range(11), color=\"0.9\")"}]},{"title":"Set Text in the Plot","body":["Next, we will set the text in the plot using the text() function. We will use the math_fontfamily parameter to change the font family for each individual text element."],"code":[{"lang":"python","text":"# A text mixing normal text and math text.\nmsg = (r\"Normal Text. $Text\\ in\\ math\\ mode:\\ \"\n       r\"\\int_{0}^{\\infty } x^2 dx$\")\n\n# Set the text in the plot.\nax.text(1, 7, msg, size=12, math_fontfamily='cm')\n\n# Set another font for the next text.\nax.text(1, 3, msg, size=12, math_fontfamily='dejavuserif')"}]},{"title":"Set Font for the Title","body":["We can also change the font family for the title using the math_fontfamily parameter."],"code":[{"lang":"python","text":"ax.set_title(r\"$Title\\ in\\ math\\ mode:\\ \\int_{0}^{\\infty } x^2 dx$\",\n             math_fontfamily='stixsans', size=14)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-mathtext-wx-sgskip":{"intro":"This lab will guide you through creating a wxPython application that displays math text in a wx.Bitmap for display in various controls on wxPython. It uses the Matplotlib library to convert text to images and the wxPython library to display the images.","steps":[{"title":"Install Required Libraries","body":["To complete this lab, you need to have the following libraries installed:","You can install these libraries using pip."],"code":[{"lang":"python","text":"pip install wxPython\npip install matplotlib"}]},{"title":"Create a wxPython Application","body":["Create a new Python file and import the required libraries."],"code":[{"lang":"python","text":"import wx\nimport numpy as np\nfrom io import BytesIO\nfrom matplotlib.backends.backend_wxagg import FigureCanvasWxAgg as FigureCanvas\nfrom matplotlib.figure import Figure"}]},{"title":"Convert Mathtext to wx.Bitmap","body":["Define a function that converts math text to a wx.Bitmap. This function uses Matplotlib to draw the text at position (0, 0) but then relies on facecolor=\"none\" and bbox_inches=\"tight\", pad_inches=0 to get a transparent mask that is then loaded into a wx.Bitmap."],"code":[{"lang":"python","text":"def mathtext_to_wxbitmap(s):\n    fig = Figure(facecolor=\"none\")\n    text_color = (\n        np.array(wx.SystemSettings.GetColour(wx.SYS_COLOUR_WINDOWTEXT)) / 255)\n    fig.text(0, 0, s, fontsize=10, color=text_color)\n    buf = BytesIO()\n    fig.savefig(buf, format=\"png\", dpi=150, bbox_inches=\"tight\", pad_inches=0)\n    s = buf.getvalue()\n    return wx.Bitmap.NewFromPNGData(s, len(s))"}]},{"title":"Define Functions","body":["Define a list of functions that the application will display. Each function is defined by a math text and a lambda function that takes an input value and returns an output value."],"code":[{"lang":"python","text":"functions = [\n    (r'$\\sin(2 \\pi x)$', lambda x: np.sin(2*np.pi*x)),\n    (r'$\\frac{4}{3}\\pi x^3$', lambda x: (4/3)*np.pi*x**3),\n    (r'$\\cos(2 \\pi x)$', lambda x: np.cos(2*np.pi*x)),\n    (r'$\\log(x)$', lambda x: np.log(x))\n]"}]},{"title":"Create a Canvas Frame","body":["Create a new class that inherits from wx.Frame. This class creates a canvas that displays the selected function."],"code":[{"lang":"python","text":"class CanvasFrame(wx.Frame):\n    def __init__(self, parent, title):\n        super().__init__(parent, -1, title, size=(550, 350))\n\n        self.figure = Figure()\n        self.axes = self.figure.add_subplot()\n\n        self.canvas = FigureCanvas(self, -1, self.figure)\n\n        self.change_plot(0)\n\n        self.sizer = wx.BoxSizer(wx.VERTICAL)\n        self.add_buttonbar()\n        self.sizer.Add(self.canvas, 1, wx.LEFT | wx.TOP | wx.GROW)\n\n        self.SetSizer(self.sizer)\n        self.Fit()"}]},{"title":"Add a Button Bar","body":[],"code":[{"lang":"python","text":"def add_buttonbar(self):\n        self.button_bar = wx.Panel(self)\n        self.button_bar_sizer = wx.BoxSizer(wx.HORIZONTAL)\n        self.sizer.Add(self.button_bar, 0, wx.LEFT | wx.TOP | wx.GROW)\n\n        for i, (mt, func) in enumerate(functions):\n            bm = mathtext_to_wxbitmap(mt)\n            button = wx.BitmapButton(self.button_bar, 1000 + i, bm)\n            self.button_bar_sizer.Add(button, 1, wx.GROW)\n            self.Bind(wx.EVT_BUTTON, self.OnChangePlot, button)\n\n        self.button_bar.SetSizer(self.button_bar_sizer)"}]},{"title":"Add a Toolbar","body":["Add a toolbar to the application that allows the user to zoom in and out, pan, and save the plot as an image. This toolbar is added to the bottom of the frame."],"code":[{"lang":"python","text":"def add_toolbar(self):\n        self.toolbar = NavigationToolbar2Wx(self.canvas)\n        self.toolbar.Realize()\n        self.sizer.Add(self.toolbar, 0, wx.LEFT | wx.EXPAND)\n        self.toolbar.update()"}]},{"title":"Change the Plot","body":["Define a function that changes the plot based on the selected function. This function takes a plot_number as input and changes the plot accordingly."],"code":[{"lang":"python","text":"def change_plot(self, plot_number):\n        t = np.arange(1.0, 3.0, 0.01)\n        s = functions[plot_number][1](t)\n        self.axes.clear()\n        self.axes.plot(t, s)\n        self.canvas.draw()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == \"__main__\":\n    app = MyApp()\n    app.MainLoop()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-visualize-2d-arrays-with-matplotlib":{"intro":"Matplotlib is a popular data visualization library in Python. It can be used to create a variety of different types of plots and charts. One of the functions provided by Matplotlib is matshow(), which can be used to visualize a 2D matrix or array as a color-coded image. In this lab, we will go through the steps to use matshow() to visualize a 2D array.","steps":[{"title":"Import Required Libraries","body":["To use matshow(), we will need to import the Matplotlib library. We will also use NumPy to create a 2D array for visualization."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the 2D Array","body":["Next, we will create a 2D array using NumPy. In this example, we will create a diagonal matrix with values ranging from 0 to 14."],"code":[{"lang":"python","text":"a = np.diag(range(15))"}]},{"title":"Visualize the 2D Array using matshow()","body":["Visualize the 2D Array using matshow()","Now we can use matshow() to visualize the 2D array as a color-coded image."],"code":[{"lang":"python","text":"plt.matshow(a)\nplt.show()"}]},{"title":"Interpret the Visualization","body":["In the visualization generated by matshow(), each value in the 2D array is represented by a color. The color map used by default in Matplotlib is a gradient from blue to red, with blue representing the lowest values and red representing the highest values. In this particular visualization, the diagonal of the matrix is white, which indicates that the values on the diagonal are the highest in the matrix."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-simple-menu-with-matplotlib":{"intro":"In this lab, you will learn how to create a simple menu using Matplotlib. The menu will contain a list of items, each of which can be selected by the user. The selected item will then trigger a callback function that will perform some action.","steps":[{"title":"Import Libraries","body":["To get started, we need to import the necessary libraries. In this case, we need to import matplotlib.pyplot, matplotlib.artist, matplotlib.patches, and IdentityTransform from matplotlib.transforms."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.artist as artist\nimport matplotlib.patches as patches\nfrom matplotlib.transforms import IdentityTransform"}]},{"title":"Define ItemProperties class","body":["Next, we define a ItemProperties class which will be used to set the properties for each menu item. We can set the font size, label color, background color, and alpha value for each item using this class."],"code":[{"lang":"python","text":"class ItemProperties:\n    def __init__(self, fontsize=14, labelcolor='black', bgcolor='yellow',\n                 alpha=1.0):\n        self.fontsize = fontsize\n        self.labelcolor = labelcolor\n        self.bgcolor = bgcolor\n        self.alpha = alpha"}]},{"title":"Define MenuItem class","body":["Now we define a MenuItem class which will be used to create each item in the menu. We pass the figure, label string, properties, hover properties, and on select callback function as parameters to this class. The MenuItem class inherits from the artist.Artist class."],"code":[{"lang":"python","text":"class MenuItem(artist.Artist):\n    padx = 5\n    pady = 5\n\n    def __init__(self, fig, labelstr, props=None, hoverprops=None,\n                 on_select=None):\n        super().__init__()\n\n        self.set_figure(fig)\n        self.labelstr = labelstr\n\n        self.props = props if props is not None else ItemProperties()\n        self.hoverprops = (\n            hoverprops if hoverprops is not None else ItemProperties())\n        if self.props.fontsize != self.hoverprops.fontsize:\n            raise NotImplementedError(\n                'support for different font sizes not implemented')\n\n        self.on_select = on_select\n\n        # Setting the transform to IdentityTransform() lets us specify\n        # coordinates directly in pixels.\n        self.label = fig.text(0, 0, labelstr, transform=IdentityTransform(),\n                              size=props.fontsize)\n        self.text_bbox = self.label.get_window_extent(\n            fig.canvas.get_renderer())\n\n        self.rect = patches.Rectangle((0, 0), 1, 1)  # Will be updated later.\n\n        self.set_hover_props(False)\n\n        fig.canvas.mpl_connect('button_release_event', self.check_select)\n\n    def check_select(self, event):\n        over, _ = self.rect.contains(event)\n        if not over:\n            return\n        if self.on_select is not None:\n            self.on_select(self)\n\n    def set_extent(self, x, y, w, h, depth):\n        self.rect.set(x=x, y=y, width=w, height=h)\n        self.label.set(position=(x + self.padx, y + depth + self.pady/2))\n        self.hover = False\n\n    def draw(self, renderer):\n        self.rect.draw(renderer)\n        self.label.draw(renderer)"}]},{"title":"Define Menu class","body":["We also need to define a Menu class which will be used to create the menu. We pass the figure and list of menu items as parameters to this class."],"code":[{"lang":"python","text":"class Menu:\n    def __init__(self, fig, menuitems):\n        self.figure = fig\n\n        self.menuitems = menuitems\n\n        maxw = max(item.text_bbox.width for item in menuitems)\n        maxh = max(item.text_bbox.height for item in menuitems)\n        depth = max(-item.text_bbox.y0 for item in menuitems)\n\n        x0 = 100\n        y0 = 400\n\n        width = maxw + 2*MenuItem.padx\n        height = maxh + MenuItem.pady\n\n        for item in menuitems:\n            left = x0\n            bottom = y0 - maxh - MenuItem.pady\n\n            item.set_extent(left, bottom, width, height, depth)\n\n            fig.artists.append(item)\n            y0 -= maxh + MenuItem.pady\n\n        fig.canvas.mpl_connect('motion_notify_event', self.on_move)\n\n    def on_move(self, event):\n        if any(item.set_hover(event) for item in self.menuitems):\n            self.figure.canvas.draw()"}]},{"title":"Create the Menu","body":["Now we can create the menu. We create a new figure and adjust the left margin. Then we create a list of menu items and add them to the menu. We also define a callback function for each item which will print out the selected item."],"code":[{"lang":"python","text":"fig = plt.figure()\nfig.subplots_adjust(left=0.3)\nprops = ItemProperties(labelcolor='black', bgcolor='yellow',\n                       fontsize=15, alpha=0.2)\nhoverprops = ItemProperties(labelcolor='white', bgcolor='blue',\n                            fontsize=15, alpha=0.2)\n\nmenuitems = []\nfor label in ('open', 'close', 'save', 'save as', 'quit'):\n    def on_select(item):\n        print('you selected %s' % item.labelstr)\n    item = MenuItem(fig, label, props=props, hoverprops=hoverprops,\n                    on_select=on_select)\n    menuitems.append(item)\n\nmenu = Menu(fig, menuitems)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure()\nfig.subplots_adjust(left=0.3)\nprops = ItemProperties(labelcolor='black', bgcolor='yellow',\n                       fontsize=15, alpha=0.2)\nhoverprops = ItemProperties(labelcolor='white', bgcolor='blue',\n                            fontsize=15, alpha=0.2)\n\nmenuitems = []\nfor label in ('open', 'close', 'save', 'save as', 'quit'):\n    def on_select(item):\n        print('you selected %s' % item.labelstr)\n    item = MenuItem(fig, label, props=props, hoverprops=hoverprops,\n                    on_select=on_select)\n    menuitems.append(item)\n\nmenu = Menu(fig, menuitems)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-2d-and-3d-plotting":{"intro":"This lab will guide you through creating a figure that contains both a 2D and a 3D plot using Matplotlib. The 2D plot will display a damped oscillation, while the 3D plot will display a sinusoidal wave.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries for this lab. We will use Matplotlib for plotting, NumPy for creating arrays, and mpl_toolkits for 3D plotting."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.mplot3d import Axes3D"}]},{"title":"Define Functions","body":["In this step, we will define a function that generates a damped oscillation."],"code":[{"lang":"python","text":"def f(t):\n    return np.cos(2*np.pi*t) * np.exp(-t)"}]},{"title":"Create Figure","body":["In this step, we will create a figure with two subplots. The first subplot will be a 2D plot, and the second subplot will be a 3D plot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=plt.figaspect(2.))\nfig.suptitle('A Tale of 2 Subplots')"}]},{"title":"Create 2D Plot","body":["In this step, we will create a 2D plot of a damped oscillation."],"code":[{"lang":"python","text":"ax1 = fig.add_subplot(2, 1, 1)\nt1 = np.arange(0.0, 5.0, 0.1)\nt2 = np.arange(0.0, 5.0, 0.02)\nt3 = np.arange(0.0, 2.0, 0.01)\n\nax1.plot(t1, f(t1), 'bo',\n         t2, f(t2), 'k--', markerfacecolor='green')\nax1.grid(True)\nax1.set_ylabel('Damped oscillation')"}]},{"title":"Create 3D Plot","body":["In this step, we will create a 3D plot of a sinusoidal wave."],"code":[{"lang":"python","text":"ax2 = fig.add_subplot(2, 1, 2, projection='3d')\nX = np.arange(-5, 5, 0.25)\nY = np.arange(-5, 5, 0.25)\nX, Y = np.meshgrid(X, Y)\nR = np.sqrt(X**2 + Y**2)\nZ = np.sin(R)\n\nsurf = ax2.plot_surface(X, Y, Z, rstride=1, cstride=1,\n                        linewidth=0, antialiased=False)\nax2.set_zlim(-1, 1)"}]},{"title":"Show Plot","body":["In this step, we will display the figure."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-set-alternative-cursor-in-matplotlib":{"intro":"This lab will guide you on how to set an alternative cursor on a figure canvas using Matplotlib. The alternative cursor can be any of the available cursors in the Matplotlib backend tools.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the required libraries. We will be using matplotlib.pyplot and matplotlib.backend_tools."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.backend_tools import Cursors"}]},{"title":"Create a figure and set alternative cursors","body":["Create a figure and set alternative cursors","Next, we create a figure and set the alternative cursors for each subplot using a loop. We also add text to each subplot to indicate the cursor being used."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(len(Cursors), figsize=(6, len(Cursors) + 0.5), gridspec_kw={'hspace': 0})\nfig.suptitle('Hover over an Axes to see alternate Cursors')\n\nfor cursor, ax in zip(Cursors, axs):\n    ax.cursor_to_use = cursor\n    ax.text(0.5, 0.5, cursor.name,\n            horizontalalignment='center', verticalalignment='center')\n    ax.set(xticks=[], yticks=[])"}]},{"title":"Set the cursor on hover","body":["We need to set the cursor to the alternative cursor when the user hovers over a subplot. We achieve this using the motion_notify_event event and the set_cursor() function."],"code":[{"lang":"python","text":"def hover(event):\n    if fig.canvas.widgetlock.locked():\n        # Don't do anything if the zoom/pan tools have been enabled.\n        return\n\n    fig.canvas.set_cursor(\n        event.inaxes.cursor_to_use if event.inaxes else Cursors.POINTER)\n\nfig.canvas.mpl_connect('motion_notify_event', hover)"}]},{"title":"Display the figure","body":["Finally, we display the figure using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-creating-a-graph-with-glade-3":{"intro":"In this lab, you will learn how to create a simple graph using Matplotlib with Glade 3. Matplotlib is a plotting library for the Python programming language and can be used to create a wide variety of graphs and visualizations.","steps":[{"title":"Creating a Glade 3 File","body":["Next, we will create a Glade 3 file to create the user interface for our application. Open Glade 3 and create a new project. Add a ScrolledWindow widget and a Window widget. Name the window window1 and the scrolled window scrolledwindow1. Save the file as mpl_with_glade3.glade."],"code":[]},{"title":"Creating the Graph","body":["Now we can start creating our graph. First, import the necessary libraries and define the Window1Signals class. This class will handle the destroy signal for the window."],"code":[{"lang":"python","text":"from pathlib import Path\n\nimport gi\n\ngi.require_version('Gtk', '3.0')\nfrom gi.repository import Gtk\n\nimport numpy as np\n\nfrom matplotlib.backends.backend_gtk3agg import \\\n    FigureCanvasGTK3Agg as FigureCanvas\nfrom matplotlib.figure import Figure\n\n\nclass Window1Signals:\n    def on_window1_destroy(self, widget):\n        Gtk.main_quit()"}]},{"title":"Defining the Main Function","body":["Next, define the main() function. This function will create the user interface, create the graph, and display the window."],"code":[{"lang":"python","text":"def main():\n    builder = Gtk.Builder()\n    builder.add_objects_from_file(\n        str(Path(__file__).parent / \"mpl_with_glade3.glade\"),\n        (\"window1\", \"\"))\n    builder.connect_signals(Window1Signals())\n    window = builder.get_object(\"window1\")\n    sw = builder.get_object(\"scrolledwindow1\")\n\n    # Start of Matplotlib specific code\n    figure = Figure(figsize=(8, 6), dpi=71)\n    axis = figure.add_subplot()\n    t = np.arange(0.0, 3.0, 0.01)\n    s = np.sin(2*np.pi*t)\n    axis.plot(t, s)\n\n    axis.set_xlabel('time [s]')\n    axis.set_ylabel('voltage [V]')\n\n    canvas = FigureCanvas(figure)  # a Gtk.DrawingArea\n    canvas.set_size_request(800, 600)\n    sw.add(canvas)\n    # End of Matplotlib specific code\n\n    window.show_all()\n    Gtk.main()\n\nif __name__ == \"__main__\":\n    main()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def main():\n    builder = Gtk.Builder()\n    builder.add_objects_from_file(\n        str(Path(__file__).parent / \"mpl_with_glade3.glade\"),\n        (\"window1\", \"\"))\n    builder.connect_signals(Window1Signals())\n    window = builder.get_object(\"window1\")\n    sw = builder.get_object(\"scrolledwindow1\")\n\n    # Start of Matplotlib specific code\n    figure = Figure(figsize=(8, 6), dpi=71)\n    axis = figure.add_subplot()\n    t = np.arange(0.0, 3.0, 0.01)\n    s = np.sin(2*np.pi*t)\n    axis.plot(t, s)\n\n    axis.set_xlabel('time [s]')\n    axis.set_ylabel('voltage [V]')\n\n    canvas = FigureCanvas(figure)  # a Gtk.DrawingArea\n    canvas.set_size_request(800, 600)\n    sw.add(canvas)\n    # End of Matplotlib specific code\n\n    window.show_all()\n    Gtk.main()\n\nif __name__ == \"__main__\":\n    main()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-color-vision-deficiency-simulatio":{"intro":"Matplotlib is a popular data visualization library in Python. It has various built-in features, including the ability to simulate color vision deficiencies. This lab will guide you through the steps of using Matplotlib to simulate color vision deficiencies.","steps":[{"title":"Import necessary libraries and modules","body":["Import necessary libraries and modules","First, we need to import the necessary libraries and modules, including Matplotlib, NumPy, and colorspacious. We also set the color filter options that we want to simulate."],"code":[{"lang":"python","text":"import functools\nfrom pathlib import Path\n\nimport colorspacious\n\nimport numpy as np\n\n_BUTTON_NAME = \"Filter\"\n_BUTTON_HELP = \"Simulate color vision deficiencies\"\n_MENU_ENTRIES = {\n    \"None\": None,\n    \"Greyscale\": \"greyscale\",\n    \"Deuteranopia\": \"deuteranomaly\",\n    \"Protanopia\": \"protanomaly\",\n    \"Tritanopia\": \"tritanomaly\",\n}"}]},{"title":"Define the color filter function","body":["Define the color filter function","Next, we define a function that creates a color filter function based on the color filter name. This function uses the colorspacious module to convert the input image to a different color space based on the color filter name."],"code":[{"lang":"python","text":"def _get_color_filter(name):\n    \"\"\"\n    Given a color filter name, create a color filter function.\n\n    Parameters\n    ----------\n    name : str\n        The color filter name, one of the following:\n\n        - ``\"none\"``: ...\n        - ``\"greyscale\"``: Convert the input to luminosity.\n        - ``\"deuteranopia\"``: Simulate the most common form of red-green\n          colorblindness.\n        - ``\"protanopia\"``: Simulate a rarer form of red-green colorblindness.\n        - ``\"tritanopia\"``: Simulate the rare form of blue-yellow\n          colorblindness.\n\n        Color conversions use `colorspacious`_.\n\n    Returns\n    -------\n    callable\n        A color filter function that has the form:\n\n        def filter(input: np.ndarray[M, N, D])-> np.ndarray[M, N, D]\n\n        where (M, N) are the image dimensions, and D is the color depth (3 for\n        RGB, 4 for RGBA). Alpha is passed through unchanged and otherwise\n        ignored.\n    \"\"\"\n    if name not in _MENU_ENTRIES:\n        raise ValueError(f\"Unsupported filter name: {name!r}\")\n    name = _MENU_ENTRIES[name]\n\n    if name is None:\n        return None\n\n    elif name == \"greyscale\":\n        rgb_to_jch = colorspacious.cspace_converter(\"sRGB1\", \"JCh\")\n        jch_to_rgb = colorspacious.cspace_converter(\"JCh\", \"sRGB1\")\n\n        def convert(im):\n            greyscale_JCh = rgb_to_jch(im)\n            greyscale_JCh[..., 1] = 0\n            im = jch_to_rgb(greyscale_JCh)\n            return im\n\n    else:"}]},{"title":"Set menu entry","body":["We define a function that sets the menu entry based on the selected color filter name. This function updates the color filter function based on the selection."],"code":[{"lang":"python","text":"def _set_menu_entry(tb, name):\n    tb.canvas.figure.set_agg_filter(_get_color_filter(name))\n    tb.canvas.draw_idle()"}]},{"title":"Set up the toolbar","body":["Next, we define a function that sets up the toolbar based on the type of backend used. This function creates a button that allows the user to select the type of color filter to simulate."],"code":[{"lang":"python","text":"def setup(figure):\n    tb = figure.canvas.toolbar\n    if tb is None:\n        return\n    for cls in type(tb).__mro__:\n        pkg = cls.__module__.split(\".\")[0]\n        if pkg != \"matplotlib\":\n            break\n    if pkg == \"gi\":\n        _setup_gtk(tb)\n    elif pkg in (\"PyQt5\", \"PySide2\", \"PyQt6\", \"PySide6\"):\n        _setup_qt(tb)\n    elif pkg == \"tkinter\":\n        _setup_tk(tb)\n    elif pkg == \"wx\":\n        _setup_wx(tb)\n    else:\n        raise NotImplementedError(\"The current backend is not supported\")"}]},{"title":"Create sample images","body":["We create sample images to demonstrate the color filter function. We import a sample image of Grace Hopper and plot it using Matplotlib. We also create a plot of sinusoidal waves."],"code":[{"lang":"python","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    from matplotlib import cbook\n\n    plt.rcParams['figure.hooks'].append('mplcvd:setup')\n\n    fig, axd = plt.subplot_mosaic(\n        [\n            ['viridis', 'turbo'],\n            ['photo', 'lines']\n        ]\n    )\n\n    delta = 0.025\n    x = y = np.arange(-3.0, 3.0, delta)\n    X, Y = np.meshgrid(x, y)\n    Z1 = np.exp(-X**2 - Y**2)\n    Z2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\n    Z = (Z1 - Z2) * 2\n\n    imv = axd['viridis'].imshow(\n        Z, interpolation='bilinear',\n        origin='lower', extent=[-3, 3, -3, 3],\n        vmax=abs(Z).max(), vmin=-abs(Z).max()\n    )\n    fig.colorbar(imv)\n    imt = axd['turbo'].imshow(\n        Z, interpolation='bilinear', cmap='turbo',\n        origin='lower', extent=[-3, 3, -3, 3],\n        vmax=abs(Z).max(), vmin=-abs(Z).max()\n    )\n    fig.colorbar(imt)\n\n    # A sample image\n    with cbook.get_sample_data('grace_hopper.jpg') as image_file:\n        photo = plt.imread(image_file)\n    axd['photo'].imshow(photo)\n\n    th = np.linspace(0, 2*np.pi, 1024)\n    for j in [1, 2, 4, 6]:\n        axd['lines'].plot(th, np.sin(th * j), label=f'$\\\\omega={j}$')\n    axd['lines'].legend(ncols=2, loc='upper right')\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    from matplotlib import cbook\n\n    plt.rcParams['figure.hooks'].append('mplcvd:setup')\n\n    fig, axd = plt.subplot_mosaic(\n        [\n            ['viridis', 'turbo'],\n            ['photo', 'lines']\n        ]\n    )\n\n    delta = 0.025\n    x = y = np.arange(-3.0, 3.0, delta)\n    X, Y = np.meshgrid(x, y)\n    Z1 = np.exp(-X**2 - Y**2)\n    Z2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\n    Z = (Z1 - Z2) * 2\n\n    imv = axd['viridis'].imshow(\n        Z, interpolation='bilinear',\n        origin='lower', extent=[-3, 3, -3, 3],\n        vmax=abs(Z).max(), vmin=-abs(Z).max()\n    )\n    fig.colorbar(imv)\n    imt = axd['turbo'].imshow(\n        Z, interpolation='bilinear', cmap='turbo',\n        origin='lower', extent=[-3, 3, -3, 3],\n        vmax=abs(Z).max(), vmin=-abs(Z).max()\n    )\n    fig.colorbar(imt)\n\n    # A sample image\n    with cbook.get_sample_data('grace_hopper.jpg') as image_file:\n        photo = plt.imread(image_file)\n    axd['photo'].imshow(photo)\n\n    th = np.linspace(0, 2*np.pi, 1024)\n    for j in [1, 2, 4, 6]:\n        axd['lines'].plot(th, np.sin(th * j), label=f'$\\\\omega={j}$')\n    axd['lines'].legend(ncols=2, loc='upper right')\n    plt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-mri-image-visualization":{"intro":"In this lab, you will learn how to read an MRI image into a NumPy array and display it in grayscale using matplotlib library.","steps":[{"title":"Import required libraries","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cbook as cbook"}]},{"title":"Load the MRI image data","body":["We will use the get_sample_data function from matplotlib to load the sample MRI image. The image is in 256x256 16-bit integer format."],"code":[{"lang":"python","text":"with cbook.get_sample_data('s1045.ima.gz') as dfile:\n    im = np.frombuffer(dfile.read(), np.uint16).reshape((256, 256))"}]},{"title":"Display the MRI image","body":["We will use imshow function from matplotlib to display the MRI image in grayscale."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(num=\"MRI_demo\")\nax.imshow(im, cmap=\"gray\")\nax.axis('off')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(num=\"MRI_demo\")\nax.imshow(im, cmap=\"gray\")\nax.axis('off')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-mri-with-eeg-visualization":{"intro":"This lab will guide you through creating a visualization of an MRI image with EEG traces using Python Matplotlib. You will learn how to load and display MRI and EEG data, plot an intensity histogram of the MRI image, and plot EEG traces with time on the x-axis and electrode channels on the y-axis.","steps":[{"title":"Load MRI Data and Display the Image","body":["Load MRI Data and Display the Image","The first step is to load the MRI data and display the image. We will use the imshow() function to display the image and axis('off') to remove the axis labels."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfig = plt.figure(\"MRI_with_EEG\")\n\n# Load the MRI data (256x256 16-bit integers)\nim = np.load('mri_data.npy')\n\n# Plot the MRI image\nax0 = fig.add_subplot(2, 2, 1)\nax0.imshow(im, cmap='gray')\nax0.axis('off')"}]},{"title":"Plot the Histogram of MRI Intensity","body":["Plot the Histogram of MRI Intensity","Next, we will plot the histogram of MRI intensity using the hist() function. We will normalize the intensity values to range between 0 and 1."],"code":[{"lang":"python","text":"# Plot the histogram of MRI intensity\nax1 = fig.add_subplot(2, 2, 2)\nim = np.ravel(im)\nim = im[np.nonzero(im)]  # Ignore the background\nim = im / im.max()  # Normalize\nax1.hist(im, bins=100)\nax1.set_xlabel('Intensity (a.u.)')\nax1.set_ylabel('MRI density')"}]},{"title":"Load EEG Data and Plot Traces","body":["The next step is to load the EEG data and plot the traces. We will use the fromfile() function to load the data from a file and LineCollection() to plot the traces. We will also set the y-axis tick labels to the electrode channels."],"code":[{"lang":"python","text":"# Load the EEG data\nn_samples, n_rows = 800, 4\ndata = np.load('eeg_data.npy')\nt = 10 * np.arange(n_samples) / n_samples\n\n# Plot the EEG\nax2 = fig.add_subplot(2, 1, 2)\nax2.set_xlim(0, 10)\nax2.set_xticks(np.arange(10))\ndmin = data.min()\ndmax = data.max()\ndr = (dmax - dmin) * 0.7  # Crowd them a bit.\ny0 = dmin\ny1 = (n_rows - 1) * dr + dmax\nax2.set_ylim(y0, y1)\n\nsegs = []\nfor i in range(n_rows):\n    segs.append(np.column_stack((t, data[:, i])))\n\noffsets = np.zeros((n_rows, 2), dtype=float)\noffsets[:, 1] = np.arange(n_rows) * dr\n\nlines = LineCollection(segs, offsets=offsets, transOffset=None)\nax2.add_collection(lines)\n\n# Set the yticks to use axes coordinates on the y-axis\nax2.set_yticks(offsets[:, 1])\nax2.set_yticklabels(['PG3', 'PG5', 'PG7', 'PG9'])\nax2.set_xlabel('Time (s)')"}]},{"title":"Display the Visualization","body":["Finally, we will display the visualization using the show() function."],"code":[{"lang":"python","text":"plt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-colormap-image-generation":{"intro":"This tutorial will guide you through the process of making a set of images with a single colormap, norm, and colorbar in Python's Matplotlib library. You will learn how to generate data, set color scales, and update images to respond to changes in the norm of other images.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries: numpy and matplotlib. We will also set a random seed to ensure reproducibility."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data and Create Subplots","body":["Generate Data and Create Subplots","Next, we will generate data for our images. We will create a 3x2 grid of subplots, with each subplot containing a randomly generated array of values."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nNr = 3\nNc = 2\n\nfig, axs = plt.subplots(Nr, Nc)\nfig.suptitle('Multiple images')\n\nimages = []\nfor i in range(Nr):\n    for j in range(Nc):\n        # Generate data with a range that varies from one plot to the next.\n        data = ((1 + i + j) / 10) * np.random.rand(10, 20)\n        images.append(axs[i, j].imshow(data))\n        axs[i, j].label_outer()"}]},{"title":"Set Color Scale and Create Colorbar","body":["Set Color Scale and Create Colorbar","Now, we will set the color scale for our images and create a colorbar to show the range of values. We will find the minimum and maximum values for all images and normalize the color scale accordingly."],"code":[{"lang":"python","text":"vmin = min(image.get_array().min() for image in images)\nvmax = max(image.get_array().max() for image in images)\nnorm = colors.Normalize(vmin=vmin, vmax=vmax)\nfor im in images:\n    im.set_norm(norm)\n\nfig.colorbar(images[0], ax=axs, orientation='horizontal', fraction=.1)"}]},{"title":"Update Images","body":["Finally, we will update the images to respond to changes in the norm of other images. This will allow us to change the colormap and color scale of one image and have all others update accordingly."],"code":[{"lang":"python","text":"def update(changed_image):\n    for im in images:\n        if (changed_image.get_cmap() != im.get_cmap()\n                or changed_image.get_clim() != im.get_clim()):\n            im.set_cmap(changed_image.get_cmap())\n            im.set_clim(changed_image.get_clim())\n\nfor im in images:\n    im.callbacks.connect('changed', update)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def update(changed_image):\n    for im in images:\n        if (changed_image.get_cmap() != im.get_cmap()\n                or changed_image.get_clim() != im.get_clim()):\n            im.set_cmap(changed_image.get_cmap())\n            im.set_clim(changed_image.get_clim())\n\nfor im in images:\n    im.callbacks.connect('changed', update)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-multicolored-matplotlib-lines":{"intro":"In this lab, we will learn how to create multicolored lines in Matplotlib. We will use the LineCollection function to create a set of line segments and color them individually based on their derivative. We will also learn how to use a boundary norm to color the line segments.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries for this lab. We will import matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["We will create a numpy array x containing 500 evenly spaced values between 0 and 3π. We will also create another numpy array y containing the sine of the values in x. Finally, we will create a numpy array dydx containing the first derivative of y."],"code":[{"lang":"python","text":"x = np.linspace(0, 3 * np.pi, 500)\ny = np.sin(x)\ndydx = np.cos(0.5 * (x[:-1] + x[1:]))"}]},{"title":"Create Line Segments","body":["We will create a set of line segments so that we can color them individually. We will use the numpy concatenate function to concatenate two arrays points[:-1] and points[1:] along the second axis. We will then reshape the resulting array to an N x 1 x 2 array so that we can stack points together easily to get the segments. The segments array for line collection needs to be (numlines) x (points per line) x 2 (for x and y)."],"code":[{"lang":"python","text":"points = np.array([x, y]).T.reshape(-1, 1, 2)\nsegments = np.concatenate([points[:-1], points[1:]], axis=1)"}]},{"title":"Create a Continuous Norm","body":["We will create a continuous norm to map from data points to colors. We will use the Normalize function from matplotlib.pyplot to normalize the dydx values between its minimum and maximum. We will then use the LineCollection function to create a set of line segments and color them individually based on their derivative. We will use the set_array function to set the values used for colormapping."],"code":[{"lang":"python","text":"norm = plt.Normalize(dydx.min(), dydx.max())\nlc = LineCollection(segments, cmap='viridis', norm=norm)\nlc.set_array(dydx)\nlc.set_linewidth(2)"}]},{"title":"Create a Colorbar","body":["We will create a colorbar to show the mapping between colors and dydx values. We will use the colorbar function from matplotlib.pyplot to create a colorbar."],"code":[{"lang":"python","text":"line = plt.gca().add_collection(lc)\nplt.colorbar(line)"}]},{"title":"Use a Boundary Norm","body":["We will use a boundary norm instead to color the line segments. We will create a ListedColormap containing three colors - red, green, and blue. We will then create a BoundaryNorm with boundaries -1, -0.5, 0.5, and 1, and the ListedColormap. We will use the set_array function to set the values used for colormapping."],"code":[{"lang":"python","text":"cmap = ListedColormap(['r', 'g', 'b'])\nnorm = BoundaryNorm([-1, -0.5, 0.5, 1], cmap.N)\nlc = LineCollection(segments, cmap=cmap, norm=norm)\nlc.set_array(dydx)\nlc.set_linewidth(2)"}]},{"title":"Create a Subplot","body":["We will create a subplot to show the colored line segments. We will use the subplots function from matplotlib.pyplot to create a 2x1 grid of subplots, and the sharex and sharey parameters to share the x and y axes between the subplots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 1, sharex=True, sharey=True)\nline = axs[0].add_collection(lc)\nfig.colorbar(line, ax=axs[0])"}]},{"title":"Set Axis Limits","body":["We will set the x and y axis limits for the subplots."],"code":[{"lang":"python","text":"axs[0].set_xlim(x.min(), x.max())\naxs[0].set_ylim(-1.1, 1.1)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simultaneous-cursor-display-in-matplotlib":{"intro":"This tutorial will show how to use the matplotlib.widgets.MultiCursor function to display a cursor on multiple plots simultaneously.","steps":[{"title":"Importing Libraries","body":["The first step is to import the necessary libraries which are matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating Data","body":["Next, we will create some data for our plots. In this example, we will create three sine waves with different frequencies."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns1 = np.sin(2*np.pi*t)\ns2 = np.sin(3*np.pi*t)\ns3 = np.sin(4*np.pi*t)"}]},{"title":"Creating Plots","body":["Now, we will create three subplots using the plt.subplots function. Two plots will be created in one figure, while the third plot will be created in a separate figure."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(2, sharex=True)\nax1.plot(t, s1)\nax2.plot(t, s2)\nfig, ax3 = plt.subplots()\nax3.plot(t, s3)"}]},{"title":"Adding MultiCursor","body":["Finally, we will add the MultiCursor function to display a cursor on all three plots when hovering over a data point."],"code":[{"lang":"python","text":"multi = MultiCursor(None, (ax1, ax2, ax3), color='r', lw=1)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"multi = MultiCursor(None, (ax1, ax2, ax3), color='r', lw=1)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-customized-matplotlib-visualizations":{"intro":"In this tutorial, we will learn how to create and customize plots using Matplotlib. Matplotlib is a Python library that provides a wide range of tools for creating static, animated, and interactive visualizations in Python.","steps":[{"title":"Importing Matplotlib and NumPy Libraries","body":["Importing Matplotlib and NumPy Libraries","The first step is to import the libraries. We will be using the pyplot module from Matplotlib and the numpy library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating a Figure and Subplots","body":["Creating a Figure and Subplots","The next step is to create a figure and subplots. We will create a figure with two subplots side by side using the subplots function."],"code":[{"lang":"python","text":"fig, (ax0, ax1) = plt.subplots(ncols=2, figsize=(7, 4))"}]},{"title":"Setting the Aspect Ratio and Plotting Data","body":["Setting the Aspect Ratio and Plotting Data","Now, we will set the aspect ratio of the first subplot to 1 using the set_aspect function and plot some data using the plot function."],"code":[{"lang":"python","text":"ax0.set_aspect(1)\nax0.plot(np.arange(10))"}]},{"title":"Customizing Axis Labels","body":["To customize the axis labels, we can use the set_xlabel and set_ylabel functions. We can also add newlines using the \"\\n\" character."],"code":[{"lang":"python","text":"ax0.set_xlabel('this is a xlabel\\n(with newlines!)')\nax0.set_ylabel('this is vertical\\ntest', multialignment='center')"}]},{"title":"Adding Text to the Plot","body":["We can add text to the plot using the text function. We can specify the position, rotation, horizontal and vertical alignment, and multialignment of the text."],"code":[{"lang":"python","text":"ax0.text(2, 7, 'this is\\nyet another test',\n         rotation=45,\n         horizontalalignment='center',\n         verticalalignment='top',\n         multialignment='center')"}]},{"title":"Adding Gridlines","body":["To add gridlines to the plot, we can use the grid function."],"code":[{"lang":"python","text":"ax0.grid()"}]},{"title":"Adding Multiline Text to the Second Subplot","body":["Adding Multiline Text to the Second Subplot","In the second subplot, we will add multiline text using the text function. We can specify the position, size, vertical and horizontal alignment, and bbox of the text."],"code":[{"lang":"python","text":"ax1.text(0.29, 0.4, \"Mat\\nTTp\\n123\", size=18,\n         va=\"baseline\", ha=\"right\", multialignment=\"left\",\n         bbox=dict(fc=\"none\"))\n\nax1.text(0.34, 0.4, \"Mag\\nTTT\\n123\", size=18,\n         va=\"baseline\", ha=\"left\", multialignment=\"left\",\n         bbox=dict(fc=\"none\"))\n\nax1.text(0.95, 0.4, \"Mag\\nTTT$^{A^A}$\\n123\", size=18,\n         va=\"baseline\", ha=\"right\", multialignment=\"left\",\n         bbox=dict(fc=\"none\"))"}]},{"title":"Customizing the X-Axis Labels","body":["To customize the x-axis labels, we can use the set_xticks function. We can specify the positions and labels of the ticks."],"code":[{"lang":"python","text":"ax1.set_xticks([0.2, 0.4, 0.6, 0.8, 1.],\n               labels=[\"Jan\\n2009\", \"Feb\\n2009\", \"Mar\\n2009\", \"Apr\\n2009\",\n                       \"May\\n2009\"])"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.subplots_adjust(bottom=0.25, top=0.75)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-multipage-pdf-with-matplotlib":{"intro":"In this lab, you will learn how to create a multipage PDF file with Python Matplotlib. The PDF file will contain several pages with different plots and metadata. You will also learn how to attach annotations to the PDF file.","steps":[{"title":"Import Libraries","body":["First, you need to import the necessary libraries for creating the PDF file. In this lab, we will use Matplotlib and datetime libraries."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.backends.backend_pdf import PdfPages"}]},{"title":"Create the PdfPages Object","body":["Next, you need to create a PdfPages object to which you will save the pages of the PDF file. You can use the 'with' statement to make sure that the PdfPages object is closed properly at the end of the block, even if an exception occurs."],"code":[{"lang":"python","text":"with PdfPages('multipage_pdf.pdf') as pdf:"}]},{"title":"Create the First Page","body":["In this step, you will create the first page of the PDF file. The page will contain a plot of a simple graph."],"code":[{"lang":"python","text":"plt.figure(figsize=(3, 3))\nplt.plot(range(7), [3, 1, 4, 1, 5, 9, 2], 'r-o')\nplt.title('Page One')\npdf.savefig()\nplt.close()"}]},{"title":"Create the Second Page","body":["In this step, you will create the second page of the PDF file. The page will contain a plot of a sine wave."],"code":[{"lang":"python","text":"plt.rcParams['text.usetex'] = True\nplt.figure(figsize=(8, 6))\nx = np.arange(0, 5, 0.1)\nplt.plot(x, np.sin(x), 'b-')\nplt.title('Page Two')\npdf.attach_note(\"plot of sin(x)\")  # attach metadata (as pdf note) to page\npdf.savefig()\nplt.close()"}]},{"title":"Create the Third Page","body":["In this step, you will create the third page of the PDF file. The page will contain a plot of a parabola."],"code":[{"lang":"python","text":"plt.rcParams['text.usetex'] = False\nfig = plt.figure(figsize=(4, 5))\nplt.plot(x, x ** 2, 'ko')\nplt.title('Page Three')\npdf.savefig(fig)  # or you can pass a Figure object to pdf.savefig\nplt.close()"}]},{"title":"Set the Metadata of the PDF File","body":["Set the Metadata of the PDF File","In this step, you will set the metadata of the PDF file. You can set the title, author, subject, keywords, and creation/modification date of the PDF file."],"code":[{"lang":"python","text":"d = pdf.infodict()\nd['Title'] = 'Multipage PDF Example'\nd['Author'] = 'Jouni K. Sepp\\xe4nen'\nd['Subject'] = 'How to create a multipage pdf file and set its metadata'\nd['Keywords'] = 'PdfPages multipage keywords author title subject'\nd['CreationDate'] = datetime.datetime(2009, 11, 13)\nd['ModDate'] = datetime.datetime.today()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"d = pdf.infodict()\nd['Title'] = 'Multipage PDF Example'\nd['Author'] = 'Jouni K. Sepp\\xe4nen'\nd['Subject'] = 'How to create a multipage pdf file and set its metadata'\nd['Keywords'] = 'PdfPages multipage keywords author title subject'\nd['CreationDate'] = datetime.datetime(2009, 11, 13)\nd['ModDate'] = datetime.datetime.today()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-animated-matplotlib-subplots":{"intro":"This step-by-step lab demonstrates how to create an animation with multiple subplots using Matplotlib in Python. The example shows how to animate a circle and a sine curve across two different subplots.","steps":[{"title":"Import Libraries","body":["The first step is to import the required libraries, including Matplotlib, NumPy, and Matplotlib's animation module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation\nfrom matplotlib.patches import ConnectionPatch"}]},{"title":"Create the Figure and Subplots","body":["Create the Figure and Subplots","The second step is to create the figure and subplots that will be used for the animation. In this example, we create two subplots side-by-side with different aspect ratios. The left subplot is a unit circle, and the right subplot is an empty plot that will be used to animate a sine curve."],"code":[{"lang":"python","text":"fig, (axl, axr) = plt.subplots(\n    ncols=2,\n    sharey=True,\n    figsize=(6, 2),\n    gridspec_kw=dict(width_ratios=[1, 3], wspace=0),\n)\naxl.set_aspect(1)\naxr.set_box_aspect(1 / 3)\naxr.yaxis.set_visible(False)\naxr.xaxis.set_ticks([0, np.pi, 2 * np.pi], [\"0\", r\"$\\pi$\", r\"$2\\pi$\"])"}]},{"title":"Draw the Circle and Initial Point","body":["Draw the Circle and Initial Point","The third step is to draw the circle and initial point on the left subplot. We create an array of angles to generate the circle, and then plot the sine and cosine of each angle. We also plot a single point at the origin."],"code":[{"lang":"python","text":"x = np.linspace(0, 2 * np.pi, 50)\naxl.plot(np.cos(x), np.sin(x), \"k\", lw=0.3)\npoint, = axl.plot(0, 0, \"o\")"}]},{"title":"Draw the Sine Curve","body":["The fourth step is to draw the sine curve on the right subplot. We create an array of angles, and then plot the sine of each angle. We also save the sine plot object, which we will update later in the animation."],"code":[{"lang":"python","text":"sine, = axr.plot(x, np.sin(x))"}]},{"title":"Draw the Connection Line","body":["The fifth step is to draw a dotted line connecting the two subplots. We create a ConnectionPatch object that connects the origin of the left subplot to the right edge of the right subplot. We also save the con patch object, which we will update later in the animation."],"code":[{"lang":"python","text":"con = ConnectionPatch(\n    (1, 0),\n    (0, 0),\n    \"data\",\n    \"data\",\n    axesA=axl,\n    axesB=axr,\n    color=\"C0\",\n    ls=\"dotted\",\n)\nfig.add_artist(con)"}]},{"title":"Define the Animation Function","body":["The sixth step is to define the animation function. This function will be called for each frame of the animation, and will update the position of the point on the left subplot, the position and data of the sine curve on the right subplot, and the position of the connection patch."],"code":[{"lang":"python","text":"def animate(i):\n    x = np.linspace(0, i, int(i * 25 / np.pi))\n    sine.set_data(x, np.sin(x))\n    x, y = np.cos(i), np.sin(i)\n    point.set_data([x], [y])\n    con.xy1 = x, y\n    con.xy2 = i, y\n    return point, sine, con"}]},{"title":"Create the Animation","body":["The seventh step is to create the animation object using the FuncAnimation function. We pass in the figure object, the animation function, the interval between frames in milliseconds, the number of frames, and a delay before repeating the animation."],"code":[{"lang":"python","text":"ani = animation.FuncAnimation(\n    fig,\n    animate,\n    interval=50,\n    blit=False,  # blitting can't be used with Figure artists\n    frames=x,\n    repeat_delay=100,\n)"}]},{"title":"Show the Animation","body":["The final step is to show the animation using the show function of the pyplot module."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-multiple-figs-demo":{"intro":"In this lab, you will learn how to manage multiple figures in Matplotlib's pyplot. Matplotlib is a popular data visualization library in Python, and pyplot is a sub-library within Matplotlib that provides a simple interface for creating, customizing, and organizing plots. You will learn how to create and switch between multiple figures, create subplots within each figure, and make changes to specific subplots.","steps":[{"title":"Import necessary libraries","body":["The first step is to import the necessary libraries. In this case, we need matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data","body":["Next, we need to create some data to plot. We will create two sine waves that we will plot in separate figures."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns1 = np.sin(2*np.pi*t)\ns2 = np.sin(4*np.pi*t)"}]},{"title":"Create figure 1","body":["We will begin by creating the first figure, which will contain two subplots. We will plot the first sine wave in the top subplot and twice the amplitude of the first sine wave in the bottom subplot."],"code":[{"lang":"python","text":"plt.figure(1)\n\n# Top subplot\nplt.subplot(211)\nplt.plot(t, s1)\n\n# Bottom subplot\nplt.subplot(212)\nplt.plot(t, 2*s1)"}]},{"title":"Create figure 2","body":["Next, we will create a second figure that will contain a single plot of the second sine wave."],"code":[{"lang":"python","text":"plt.figure(2)\nplt.plot(t, s2)"}]},{"title":"Make changes to figure 1","body":["Now, we will switch back to the first figure and make some changes. We will plot the second sine wave in the top subplot using square markers, and remove the x-axis tick labels from the top subplot."],"code":[{"lang":"python","text":"plt.figure(1)\n\n# Top subplot\nplt.subplot(211)\nplt.plot(t, s2, 's')\nax = plt.gca()\nax.set_xticklabels([])"}]},{"title":"Display the figures","body":["Finally, we will display the figures using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-producing-multiple-histograms-with-matplotli":{"intro":"Histograms are a great way to visualize the distribution of a dataset, and Matplotlib is one of the most popular Python libraries for creating data visualizations. In this lab, we will use Matplotlib to create side-by-side histograms for multiple datasets.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries for our code. We will use Matplotlib and NumPy for our histograms:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create example datasets","body":["Next, we will create example datasets to use for our histograms. We will create three datasets with 387 data points each:"],"code":[{"lang":"python","text":"np.random.seed(19680801)\nnumber_of_data_points = 387\nlabels = [\"A\", \"B\", \"C\"]\ndata_sets = [np.random.normal(0, 1, number_of_data_points),\n             np.random.normal(6, 1, number_of_data_points),\n             np.random.normal(-3, 1, number_of_data_points)]"}]},{"title":"Compute quantities for plotting","body":["Compute quantities for plotting","Before we can create our histograms, we need to compute some quantities for plotting. We will compute the range of our datasets, the binned data sets, the maximum bin values, and the x-locations for each histogram:"],"code":[{"lang":"python","text":"hist_range = (np.min(data_sets), np.max(data_sets))\nnumber_of_bins = 20\nbinned_data_sets = [\n    np.histogram(d, range=hist_range, bins=number_of_bins)[0]\n    for d in data_sets\n]\nbinned_maximums = np.max(binned_data_sets, axis=1)\nx_locations = np.arange(0, sum(binned_maximums), np.max(binned_maximums))"}]},{"title":"Plot the histograms","body":["Now that we have computed the necessary quantities for plotting, we can create our histograms. We will use the barh method to plot horizontal bars for each histogram:"],"code":[{"lang":"python","text":"# The bin_edges are the same for all of the histograms\nbin_edges = np.linspace(hist_range[0], hist_range[1], number_of_bins + 1)\nheights = np.diff(bin_edges)\ncenters = bin_edges[:-1] + heights / 2\n\n# Cycle through and plot each histogram\nfig, ax = plt.subplots()\nfor x_loc, binned_data in zip(x_locations, binned_data_sets):\n    lefts = x_loc - 0.5 * binned_data\n    ax.barh(centers, binned_data, height=heights, left=lefts)\n\nax.set_xticks(x_locations, labels)\nax.set_ylabel(\"Data values\")\nax.set_xlabel(\"Data sets\")"}]},{"title":"Display the histograms","body":["Finally, we can display our histograms using the show method:"],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-multiple-y-axis-plotting-with-matplotlib":{"intro":"In data visualization, it is often necessary to plot multiple variables with different units of measurement on the same graph. One common method to achieve this is by using multiple y-axes, where each y-axis corresponds to a different variable. In this lab, we will learn how to create a graph with multiple y-axes using Matplotlib.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We start by importing the required libraries, Matplotlib and NumPy. Matplotlib is a data visualization library, and NumPy is a library for numerical computing in Python."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a figure and axes object","body":["Create a figure and axes object","We create a figure and axes object, which represents a single plot in Matplotlib."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Add a twin y-axis","body":["We add a twin y-axis to the plot using the twinx method. This will create a new y-axis on the right side of the plot."],"code":[{"lang":"python","text":"twin1 = ax.twinx()"}]},{"title":"Set the position of the twin y-axis","body":["Set the position of the twin y-axis","We set the position of the twin y-axis using the set_position method. This will move the twin y-axis to the right of the original y-axis."],"code":[{"lang":"python","text":"twin1.spines.right.set_position((\"axes\", 1.2))"}]},{"title":"Add data to the plot","body":["We add data to the plot using the plot method. We add three lines to the plot, each with a different y-axis."],"code":[{"lang":"python","text":"p1, = ax.plot([0, 1, 2], [0, 1, 2], \"C0\", label=\"Density\")\np2, = twin1.plot([0, 1, 2], [0, 3, 2], \"C1\", label=\"Temperature\")\np3, = twin2.plot([0, 1, 2], [50, 30, 15], \"C2\", label=\"Velocity\")"}]},{"title":"Set the limits and labels for the axes","body":["Set the limits and labels for the axes","We set the limits and labels for each y-axis using the set method. We also set the color of the labels to match the color of the lines using the set_color method."],"code":[{"lang":"python","text":"ax.set(xlim=(0, 2), ylim=(0, 2), xlabel=\"Distance\", ylabel=\"Density\")\ntwin1.set(ylim=(0, 4), ylabel=\"Temperature\")\ntwin2.set(ylim=(1, 65), ylabel=\"Velocity\")\n\nax.yaxis.label.set_color(p1.get_color())\ntwin1.yaxis.label.set_color(p2.get_color())\ntwin2.yaxis.label.set_color(p3.get_color())"}]},{"title":"Set the tick colors","body":["We set the tick colors for each y-axis to match the color of the labels."],"code":[{"lang":"python","text":"ax.tick_params(axis='y', colors=p1.get_color())\ntwin1.tick_params(axis='y', colors=p2.get_color())\ntwin2.tick_params(axis='y', colors=p3.get_color())"}]},{"title":"Add a legend to the plot","body":["We add a legend to the plot using the legend method. We pass a list of line objects as the handles parameter."],"code":[{"lang":"python","text":"ax.legend(handles=[p1, p2, p3])"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-multiprocessing-with-matplotlib":{"intro":"In this lab, you will learn how to use the multiprocessing library and Matplotlib to plot data generated from a separate process. We will create two classes - ProcessPlotter and NBPlot - to handle the plotting and data generation, respectively. The NBPlot class will generate random data and send it to the ProcessPlotter class through a pipe, which will then plot the data in real-time.","steps":[{"title":"Import Libraries","body":["We begin by importing the necessary libraries. We will use multiprocessing to handle the separate processes, time for the time delay, numpy to generate random data, and matplotlib for the plotting."],"code":[{"lang":"python","text":"import multiprocessing as mp\nimport time\nimport numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Define the ProcessPlotter Class","body":["Define the ProcessPlotter Class","The ProcessPlotter class will handle the plotting of the data sent through the pipe. It will continuously check the pipe for new data and plot it in real-time."],"code":[{"lang":"python","text":"class ProcessPlotter:\n    def __init__(self):\n        self.x = []\n        self.y = []\n\n    def terminate(self):\n        plt.close('all')\n\n    def call_back(self):\n        while self.pipe.poll():\n            command = self.pipe.recv()\n            if command is None:\n                self.terminate()\n                return False\n            else:\n                self.x.append(command[0])\n                self.y.append(command[1])\n                self.ax.plot(self.x, self.y, 'ro')\n        self.fig.canvas.draw()\n        return True\n\n    def __call__(self, pipe):\n        print('starting plotter...')\n\n        self.pipe = pipe\n        self.fig, self.ax = plt.subplots()\n        timer = self.fig.canvas.new_timer(interval=1000)\n        timer.add_callback(self.call_back)\n        timer.start()\n\n        print('...done')\n        plt.show()"}]},{"title":"Define the NBPlot Class","body":["The NBPlot class will generate random data and send it to the ProcessPlotter class through a pipe."],"code":[{"lang":"python","text":"class NBPlot:\n    def __init__(self):\n        self.plot_pipe, plotter_pipe = mp.Pipe()\n        self.plotter = ProcessPlotter()\n        self.plot_process = mp.Process(\n            target=self.plotter, args=(plotter_pipe,), daemon=True)\n        self.plot_process.start()\n\n    def plot(self, finished=False):\n        send = self.plot_pipe.send\n        if finished:\n            send(None)\n        else:\n            data = np.random.random(2)\n            send(data)"}]},{"title":"Create an instance of NBPlot and send data to ProcessPlotter","body":["Create an instance of NBPlot and send data to ProcessPlotter","Create an instance of the NBPlot class and send random data to the ProcessPlotter class. We will send 10 sets of data, with a 0.5 second delay between each set."],"code":[{"lang":"python","text":"def main():\n    pl = NBPlot()\n    for _ in range(10):\n        pl.plot()\n        time.sleep(0.5)\n    pl.plot(finished=True)\n\nif __name__ == '__main__':\n    if plt.get_backend() == \"MacOSX\":\n        mp.set_start_method(\"forkserver\")\n    main()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def main():\n    pl = NBPlot()\n    for _ in range(10):\n        pl.plot()\n        time.sleep(0.5)\n    pl.plot(finished=True)\n\nif __name__ == '__main__':\n    if plt.get_backend() == \"MacOSX\":\n        mp.set_start_method(\"forkserver\")\n    main()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-mapping-marker-properties-to-multivariate-da":{"intro":"In this lab, you will learn how to use different properties of markers to plot multivariate datasets using Python's Matplotlib library. Specifically, you will learn how to represent a successful baseball throw as a smiley face with marker size mapped to the skill of thrower, marker rotation to the take-off angle, and thrust to the marker color.","steps":[{"title":"Import Libraries","body":["In this step, you will import the necessary libraries for this lab. Specifically, you will import Matplotlib, Numpy, and various modules from Matplotlib such as MarkerStyle, TextPath, and Affine2D."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.colors import Normalize\nfrom matplotlib.markers import MarkerStyle\nfrom matplotlib.text import TextPath\nfrom matplotlib.transforms import Affine2D"}]},{"title":"Define Success Symbols","body":["In this step, you will define the three success symbols that will be used to represent the success of a baseball throw. Specifically, you will define a smiley face for a successful throw, a neutral face for a partially successful throw, and a sad face for an unsuccessful throw."],"code":[{"lang":"python","text":"SUCCESS_SYMBOLS = [\n    TextPath((0, 0), \"☹\"),\n    TextPath((0, 0), \"😒\"),\n    TextPath((0, 0), \"☺\"),\n]"}]},{"title":"Generate Random Data","body":["In this step, you will generate random data for the skill of the thrower, take-off angle, thrust, success, and position. Specifically, you will generate 25 data points for each variable, except for position, which will have 2 coordinates for each data point."],"code":[{"lang":"python","text":"N = 25\nnp.random.seed(42)\nskills = np.random.uniform(5, 80, size=N) * 0.1 + 5\ntakeoff_angles = np.random.normal(0, 90, N)\nthrusts = np.random.uniform(size=N)\nsuccessful = np.random.randint(0, 3, size=N)\npositions = np.random.normal(size=(N, 2)) * 5\ndata = zip(skills, takeoff_angles, thrusts, successful, positions)"}]},{"title":"Define Color Map","body":["In this step, you will define the color map that will be used to map the thrust of the throw to the color of the marker. Specifically, you will use the \"plasma\" color map from Matplotlib."],"code":[{"lang":"python","text":"cmap = plt.colormaps[\"plasma\"]"}]},{"title":"Create Plot","body":["In this step, you will create the plot using the random data generated earlier. Specifically, you will plot each data point as a marker with the success symbol determined by the success variable, the size determined by the skill variable, the rotation determined by the take-off angle variable, and the color determined by the thrust variable."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.suptitle(\"Throwing success\", size=14)\nfor skill, takeoff, thrust, mood, pos in data:\n    t = Affine2D().scale(skill).rotate_deg(takeoff)\n    m = MarkerStyle(SUCCESS_SYMBOLS[mood], transform=t)\n    ax.plot(pos[0], pos[1], marker=m, color=cmap(thrust))\nfig.colorbar(plt.cm.ScalarMappable(norm=Normalize(0, 1), cmap=cmap),\n             ax=ax, label=\"Normalized Thrust [a.u.]\")\nax.set_xlabel(\"X position [m]\")\nax.set_ylabel(\"Y position [m]\")"}]},{"title":"Display Plot","body":["In this step, you will display the plot using Matplotlib's show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-nested-pie-charts-with-matplotlib":{"intro":"Pie charts are popular data visualization tools used to represent data in a circular form. However, there are times when you might want to create a nested version of the pie chart, known as the donut chart. This tutorial will guide you through creating nested pie charts using Matplotlib, a popular data visualization library in Python.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. In this case, we need Matplotlib and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a nested pie chart using ax.pie","body":["Create a nested pie chart using ax.pie","We can create a nested pie chart using ax.pie method. We will first generate some fake data, corresponding to three groups. In the inner circle, we'll treat each number as belonging to its own group. In the outer circle, we'll plot them as members of their original 3 groups."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nsize = 0.3\nvals = np.array([[60., 32.], [37., 40.], [29., 10.]])\n\ncmap = plt.colormaps[\"tab20c\"]\nouter_colors = cmap(np.arange(3)*4)\ninner_colors = cmap([1, 2, 5, 6, 9, 10])\n\nax.pie(vals.sum(axis=1), radius=1, colors=outer_colors,\n       wedgeprops=dict(width=size, edgecolor='w'))\n\nax.pie(vals.flatten(), radius=1-size, colors=inner_colors,\n       wedgeprops=dict(width=size, edgecolor='w'))\n\nax.set(aspect=\"equal\", title='Pie plot with `ax.pie`')\nplt.show()"}]},{"title":"Create a nested pie chart using ax.bar","body":["Create a nested pie chart using ax.bar","We can also create a nested pie chart using ax.bar method on axes with a polar coordinate system. This may give more flexibility on the exact design of the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw=dict(projection=\"polar\"))\n\nsize = 0.3\nvals = np.array([[60., 32.], [37., 40.], [29., 10.]])\n# Normalize vals to 2 pi\nvalsnorm = vals/np.sum(vals)*2*np.pi\n# Obtain the ordinates of the bar edges\nvalsleft = np.cumsum(np.append(0, valsnorm.flatten()[:-1])).reshape(vals.shape)\n\ncmap = plt.colormaps[\"tab20c\"]\nouter_colors = cmap(np.arange(3)*4)\ninner_colors = cmap([1, 2, 5, 6, 9, 10])\n\nax.bar(x=valsleft[:, 0],\n       width=valsnorm.sum(axis=1), bottom=1-size, height=size,\n       color=outer_colors, edgecolor='w', linewidth=1, align=\"edge\")\n\nax.bar(x=valsleft.flatten(),\n       width=valsnorm.flatten(), bottom=1-2*size, height=size,\n       color=inner_colors, edgecolor='w', linewidth=1, align=\"edge\")\n\nax.set(title=\"Pie plot with `ax.bar` and polar coordinates\")\nax.set_axis_off()\nplt.show()"}]},{"title":"Customize the Nested Pie Chart","body":["Customize the Nested Pie Chart","We can customize the nested pie chart by changing the colors, adding labels, and adjusting the size."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nsize = 0.3\nvals = np.array([[60., 32.], [37., 40.], [29., 10.]])\n\ncmap = plt.colormaps[\"tab20c\"]\nouter_colors = cmap(np.arange(3)*4)\ninner_colors = cmap([1, 2, 5, 6, 9, 10])\n\n# Add labels\nlabels = ['Group 1', 'Group 2', 'Group 3']\nax.pie(vals.sum(axis=1), radius=1, colors=outer_colors,\n       wedgeprops=dict(width=size, edgecolor='w'), labels=labels, labeldistance=0.7)\n\nax.pie(vals.flatten(), radius=1-size, colors=inner_colors,\n       wedgeprops=dict(width=size, edgecolor='w'))\n\n# Set the title\nax.set(aspect=\"equal\", title='Nested Pie Chart')\n\nplt.show()"}]},{"title":"Save the Nested Pie Chart","body":["We can save the nested pie chart as an image in png, pdf, or svg format."],"code":[{"lang":"python","text":"fig.savefig('nested_pie_chart.png', dpi=300, bbox_inches='tight')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.savefig('nested_pie_chart.png', dpi=300, bbox_inches='tight')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-3d-plots-with-matplotlib-in-python":{"intro":"This lab will guide you through the process of creating a 3D plot using Matplotlib in Python.","steps":[{"title":"Import Necessary Libraries","body":["We begin by importing the necessary libraries. In this case, we need NumPy and Matplotlib."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import Axes3D"}]},{"title":"Create Data","body":["Next, we create the data that we will use in our plot. In this example, we will be using NumPy to generate the data."],"code":[{"lang":"python","text":"x = np.linspace(-5, 5, 100)\ny = np.linspace(-5, 5, 100)\nX, Y = np.meshgrid(x, y)\nZ = np.sin(np.sqrt(X ** 2 + Y ** 2))"}]},{"title":"Create the Figure and Axes Objects","body":["Create the Figure and Axes Objects","Now, we create a figure and axes object that we will use to create the plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(111, projection='3d')"}]},{"title":"Create the Plot","body":["Finally, we create the plot using the data and the axes object we just created."],"code":[{"lang":"python","text":"ax.plot_surface(X, Y, Z)\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_zlabel('Z Label')"}]},{"title":"Display the Plot","body":["We display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-packed-bubble-charts-with-python":{"intro":"In this lab, we will learn how to create a packed-bubble chart using Matplotlib in Python. The packed-bubble chart is a type of chart that displays data in bubbles of different sizes, with the bubble's size representing the data's magnitude. This chart is useful for displaying scalar data, where the data is a single numeric value associated with an item.","steps":[{"title":"Import Required Libraries","body":["To create a packed-bubble chart, we need to import the matplotlib.pyplot and numpy libraries. The numpy library is used to perform mathematical operations on arrays, which is useful for calculating bubble sizes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Data","body":[],"code":[{"lang":"python","text":"browser_market_share = {\n    'browsers': ['firefox', 'chrome', 'safari', 'edge', 'ie', 'opera'],\n    'market_share': [8.61, 69.55, 8.36, 4.12, 2.76, 2.43],\n    'color': ['#5A69AF', '#579E65', '#F9C784', '#FC944A', '#F24C00', '#00B825']\n}"}]},{"title":"Define BubbleChart Class","body":["The BubbleChart class is used to create the packed-bubble chart. The class takes in an array of bubble areas and a bubble spacing value. The __init__ method sets up the initial positions of the bubbles and calculates the maximum step distance, which is the distance each bubble can move in a single iteration."],"code":[{"lang":"python","text":"class BubbleChart:\n    def __init__(self, area, bubble_spacing=0):\n        \"\"\"\n        Setup for bubble collapse.\n\n        Parameters\n        ----------\n        area : array-like\n            Area of the bubbles.\n        bubble_spacing : float, default: 0\n            Minimal spacing between bubbles after collapsing.\n\n        Notes\n        -----\n        If \"area\" is sorted, the results might look weird.\n        \"\"\"\n        area = np.asarray(area)\n        r = np.sqrt(area / np.pi)\n\n        self.bubble_spacing = bubble_spacing\n        self.bubbles = np.ones((len(area), 4))\n        self.bubbles[:, 2] = r\n        self.bubbles[:, 3] = area\n        self.maxstep = 2 * self.bubbles[:, 2].max() + self.bubble_spacing\n        self.step_dist = self.maxstep / 2\n\n        # calculate initial grid layout for bubbles\n        length = np.ceil(np.sqrt(len(self.bubbles)))\n        grid = np.arange(length) * self.maxstep\n        gx, gy = np.meshgrid(grid, grid)\n        self.bubbles[:, 0] = gx.flatten()[:len(self.bubbles)]\n        self.bubbles[:, 1] = gy.flatten()[:len(self.bubbles)]\n\n        self.com = self.center_of_mass()"}]},{"title":"Define Bubble Movement Methods","body":["Define Bubble Movement Methods","The BubbleChart class also contains methods to move the bubbles towards the center of mass and check for collisions with other bubbles. The center_of_mass method calculates the center of mass of all the bubbles, and the center_distance method calculates the distance between a bubble and the center of mass. The outline_distance method calculates the distance between a bubble's outline and the outlines of other bubbles, and the check_collisions method checks if a new bubble position collides with other bubbles."],"code":[{"lang":"python","text":"def center_of_mass(self):\n        return np.average(\n            self.bubbles[:, :2], axis=0, weights=self.bubbles[:, 3]\n        )\n\n    def center_distance(self, bubble, bubbles):\n        return np.hypot(bubble[0] - bubbles[:, 0],\n                        bubble[1] - bubbles[:, 1])\n\n    def outline_distance(self, bubble, bubbles):\n        center_distance = self.center_distance(bubble, bubbles)\n        return center_distance - bubble[2] - \\\n            bubbles[:, 2] - self.bubble_spacing\n\n    def check_collisions(self, bubble, bubbles):\n        distance = self.outline_distance(bubble, bubbles)\n        return len(distance[distance < 0])"}]},{"title":"Define Bubble Collision Method","body":["Define Bubble Collision Method","The BubbleChart class also contains a method to check for bubble collisions and move around colliding bubbles. The collides_with method calculates the distance between a new bubble position and the positions of other bubbles. If the distance is less than zero, it means there is a collision, and the method returns the index of the colliding bubble. The collapse method moves the bubbles towards the center of mass and around colliding bubbles, and the plot method draws the bubbles on the chart."],"code":[{"lang":"python","text":"def collides_with(self, bubble, bubbles):\n        distance = self.outline_distance(bubble, bubbles)\n        idx_min = np.argmin(distance)\n        return idx_min if type(idx_min) == np.ndarray else [idx_min]\n\n    def collapse(self, n_iterations=50):\n        \"\"\"\n        Move bubbles to the center of mass.\n\n        Parameters\n        ----------\n        n_iterations : int, default: 50\n            Number of moves to perform.\n        \"\"\"\n        for _i in range(n_iterations):\n            moves = 0\n            for i in range(len(self.bubbles)):\n                rest_bub = np.delete(self.bubbles, i, 0)\n                # try to move directly towards the center of mass\n                # direction vector from bubble to the center of mass\n                dir_vec = self.com - self.bubbles[i, :2]\n\n                # shorten direction vector to have length of 1\n                dir_vec = dir_vec / np.sqrt(dir_vec.dot(dir_vec))\n\n                # calculate new bubble position\n                new_point = self.bubbles[i, :2] + dir_vec * self.step_dist\n                new_bubble = np.append(new_point, self.bubbles[i, 2:4])\n\n                # check whether new bubble collides with other bubbles\n                if not self.check_collisions(new_bubble, rest_bub):\n                    self.bubbles[i, :] = new_bubble\n                    self.com = self.center_of_mass()\n                    moves += 1\n                else:\n                    # try to move around a bubble that you collide with\n                    # find colliding bubble\n                    for colliding in self.collides_with(new_bubble, rest_bub):\n                        # calculate direction vector\n                        dir_vec = rest_bub[colliding, :2] - self.bubbles[i, :2]\n                        dir_vec = dir_vec / np.sqrt(dir_vec.dot(dir_vec))\n                        # calculate orthogonal vector\n                        orth = np.array([dir_vec[1], -dir_vec[0]])\n                        # test which direction to go\n                        new_point1 = (self.bubbles[i, :2] + orth *\n                                      self.step_dist)\n                        new_point2 = (self.bubbles[i, :2] - orth *\n                                      self.step_dist)"}]},{"title":"Create BubbleChart Object and Plot Chart","body":["Create BubbleChart Object and Plot Chart","To create the packed-bubble chart, we need to create a BubbleChart object and call the collapse method to move the bubbles towards the center of mass. We can then create a matplotlib figure and add an axes object to it. Finally, we call the plot method to draw the bubbles on the chart."],"code":[{"lang":"python","text":"bubble_chart = BubbleChart(area=browser_market_share['market_share'],\n                           bubble_spacing=0.1)\n\nbubble_chart.collapse()\n\nfig, ax = plt.subplots(subplot_kw=dict(aspect=\"equal\"))\nbubble_chart.plot(\n    ax, browser_market_share['browsers'], browser_market_share['color'])\nax.axis(\"off\")\nax.relim()\nax.autoscale_view()\nax.set_title('Browser market share')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"bubble_chart = BubbleChart(area=browser_market_share['market_share'],\n                           bubble_spacing=0.1)\n\nbubble_chart.collapse()\n\nfig, ax = plt.subplots(subplot_kw=dict(aspect=\"equal\"))\nbubble_chart.plot(\n    ax, browser_market_share['browsers'], browser_market_share['color'])\nax.axis(\"off\")\nax.relim()\nax.autoscale_view()\nax.set_title('Browser market share')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-line-plot-with-dual-axes":{"intro":"In this lab, we will learn how to create a line plot with dual axes using Matplotlib library in Python. We will plot two sets of data with different scales on the same graph. This is useful when we want to compare two related variables that have different units of measurement.","steps":[{"title":"Importing Libraries","body":["We will start by importing the necessary libraries. We will need matplotlib.pyplot for creating the graph and mpl_toolkits.axes_grid1 for creating the dual axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import host_subplot"}]},{"title":"Creating the Plot","body":["Next, we will create the plot by defining the host axis and the parasite axis. The host axis will be used for the primary data and the parasite axis will be used for the secondary data."],"code":[{"lang":"python","text":"host = host_subplot(111)\npar = host.twinx()"}]},{"title":"Setting Labels","body":["We will set the labels for both axes and the title for the plot."],"code":[{"lang":"python","text":"host.set_xlabel(\"Distance\")\nhost.set_ylabel(\"Density\")\npar.set_ylabel(\"Temperature\")\nplt.title(\"Density and Temperature vs Distance\")"}]},{"title":"Adding Data","body":["We will add the data to the plot by using the plot function. We will assign each line to a variable so that we can reference it later."],"code":[{"lang":"python","text":"p1, = host.plot([0, 1, 2], [0, 1, 2], label=\"Density\")\np2, = par.plot([0, 1, 2], [0, 3, 2], label=\"Temperature\")"}]},{"title":"Formatting the Plot","body":["We will format the plot by setting the legend, label colors, and line colors."],"code":[{"lang":"python","text":"host.legend()\nhost.yaxis.get_label().set_color(p1.get_color())\npar.yaxis.get_label().set_color(p2.get_color())"}]},{"title":"Displaying the Plot","body":["Finally, we will display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-dual-y-axis-matplotlib-plots":{"intro":"In this tutorial, you will learn how to create a plot with two y-axes using Matplotlib. The plot will display two sets of data with different units of measurement on different scales. This type of plot is commonly used in scientific research to visualize relationships between variables that are not directly comparable.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using Matplotlib and its parasite_axes module to create the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.transforms as mtransforms\nfrom mpl_toolkits.axes_grid1.parasite_axes import HostAxes"}]},{"title":"Define Data","body":["Next, we need to define the data that will be plotted. In this example, we have a set of observations with four variables: name, angular proper motion, angular proper motion error, and distance. We will convert the angular proper motion to linear velocity and plot it against the FWHM (full width at half maximum) of the observations."],"code":[{"lang":"python","text":"obs = [[\"01_S1\", 3.88, 0.14, 1970, 63],\n       [\"01_S4\", 5.6, 0.82, 1622, 150],\n       [\"02_S1\", 2.4, 0.54, 1570, 40],\n       [\"03_S1\", 4.1, 0.62, 2380, 170]]\n\n# Conversion factor from angular proper motion to linear velocity\npm_to_kms = 1./206265.*2300*3.085e18/3.15e7/1.e5"}]},{"title":"Create the Plot","body":["We will now create the plot using the HostAxes and twin() functions from the parasite_axes module. HostAxes is used to create the main plot, and twin() is used to create the secondary y-axis."],"code":[{"lang":"python","text":"fig = plt.figure()\n\n# Create HostAxes object\nax_kms = fig.add_subplot(axes_class=HostAxes, aspect=1)\n\n# Create secondary y-axis with transformed coordinates\naux_trans = mtransforms.Affine2D().scale(pm_to_kms, 1.)\nax_pm = ax_kms.twin(aux_trans)\n\n# Plot the data\nfor n, ds, dse, w, we in obs:\n    time = ((2007 + (10. + 4/30.)/12) - 1988.5)\n    v = ds / time * pm_to_kms\n    ve = dse / time * pm_to_kms\n    ax_kms.errorbar([v], [w], xerr=[ve], yerr=[we], color=\"k\")\n\n# Set the axis labels\nax_kms.axis[\"bottom\"].set_label(\"Linear velocity at 2.3 kpc [km/s]\")\nax_kms.axis[\"left\"].set_label(\"FWHM [km/s]\")\nax_pm.axis[\"top\"].set_label(r\"Proper Motion [$''$/yr]\")\n\n# Hide the tick labels on the secondary y-axis\nax_pm.axis[\"right\"].major_ticklabels.set_visible(False)\n\n# Set the plot limits\nax_kms.set_xlim(950, 3700)\nax_kms.set_ylim(950, 3100)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-shapes-with-python-matplotlib":{"intro":"This tutorial is designed to guide users on how to create circles, wedges and polygons using Python Matplotlib. Users will also be able to use .collections.PatchCollection to visualize the created shapes.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.collections import PatchCollection\nfrom matplotlib.patches import Circle, Polygon, Wedge"}]},{"title":"Create a figure and an axis","body":["We create a figure and an axis to plot the shapes."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Define the number of vertices and the number of shapes","body":["Define the number of vertices and the number of shapes","We define the number of vertices and the number of shapes to create."],"code":[{"lang":"python","text":"resolution = 50  # the number of vertices\nN = 3"}]},{"title":"Create circles","body":["We create circles using Circle() and append them to a list of patches."],"code":[{"lang":"python","text":"x = np.random.rand(N)\ny = np.random.rand(N)\nradii = 0.1*np.random.rand(N)\npatches = []\nfor x1, y1, r in zip(x, y, radii):\n    circle = Circle((x1, y1), r)\n    patches.append(circle)"}]},{"title":"Create wedges","body":["We create wedges using Wedge() and append them to the list of patches."],"code":[{"lang":"python","text":"x = np.random.rand(N)\ny = np.random.rand(N)\nradii = 0.1*np.random.rand(N)\ntheta1 = 360.0*np.random.rand(N)\ntheta2 = 360.0*np.random.rand(N)\nfor x1, y1, r, t1, t2 in zip(x, y, radii, theta1, theta2):\n    wedge = Wedge((x1, y1), r, t1, t2)\n    patches.append(wedge)"}]},{"title":"Add limiting conditions to wedges","body":["Add limiting conditions to wedges","We add limiting conditions to wedges."],"code":[{"lang":"python","text":"patches += [\n    Wedge((.3, .7), .1, 0, 360),             # Full circle\n    Wedge((.7, .8), .2, 0, 360, width=0.05),  # Full ring\n    Wedge((.8, .3), .2, 0, 45),              # Full sector\n    Wedge((.8, .3), .2, 45, 90, width=0.10),  # Ring sector\n]"}]},{"title":"Create polygons","body":["We create polygons using Polygon() and append them to the list of patches."],"code":[{"lang":"python","text":"for i in range(N):\n    polygon = Polygon(np.random.rand(N, 2), closed=True)\n    patches.append(polygon)"}]},{"title":"Set colors and create PatchCollection","body":["Set colors and create PatchCollection","We set the colors of the shapes and create a PatchCollection()."],"code":[{"lang":"python","text":"colors = 100 * np.random.rand(len(patches))\np = PatchCollection(patches, alpha=0.4)\np.set_array(colors)\nax.add_collection(p)\nfig.colorbar(p, ax=ax)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-interactive-matplotlib-canvas-editing":{"intro":"This lab will guide you through an example of a cross-GUI application using Matplotlib event handling to interact with and modify objects on the canvas. You will learn how to edit a path on a plot, by dragging markers with the mouse, and toggling their visibility.","steps":[{"title":"Import Libraries","body":["In this step, we import the necessary libraries for the lab. We use Matplotlib to create the plot and handle events."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.backend_bases import MouseButton\nfrom matplotlib.patches import PathPatch\nfrom matplotlib.path import Path"}]},{"title":"Create the Plot","body":["In this step, we create a plot with a green path and yellow edges, using the path data provided. We then add a PathPatch object to the plot, which represents the path."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\npathdata = [\n    (Path.MOVETO, (1.58, -2.57)),\n    (Path.CURVE4, (0.35, -1.1)),\n    (Path.CURVE4, (-1.75, 2.0)),\n    (Path.CURVE4, (0.375, 2.0)),\n    (Path.LINETO, (0.85, 1.15)),\n    (Path.CURVE4, (2.2, 3.2)),\n    (Path.CURVE4, (3, 0.05)),\n    (Path.CURVE4, (2.0, -0.5)),\n    (Path.CLOSEPOLY, (1.58, -2.57)),\n]\n\ncodes, verts = zip(*pathdata)\npath = Path(verts, codes)\npatch = PathPatch(\n    path, facecolor='green', edgecolor='yellow', alpha=0.5)\nax.add_patch(patch)"}]},{"title":"Create the PathInteractor Class","body":["Create the PathInteractor Class","In this step, we create the PathInteractor class, which handles the event callbacks for the path object. This class allows us to interactively edit the path by dragging markers on the plot."],"code":[{"lang":"python","text":"class PathInteractor:\n    \"\"\"\n    A path editor.\n\n    Press 't' to toggle vertex markers on and off.  When vertex markers are on,\n    they can be dragged with the mouse.\n    \"\"\"\n\n    showverts = True\n    epsilon = 5  # max pixel distance to count as a vertex hit\n\n    def __init__(self, pathpatch):\n\n        self.ax = pathpatch.axes\n        canvas = self.ax.figure.canvas\n        self.pathpatch = pathpatch\n        self.pathpatch.set_animated(True)\n\n        x, y = zip(*self.pathpatch.get_path().vertices)\n\n        self.line, = ax.plot(\n            x, y, marker='o', markerfacecolor='r', animated=True)\n\n        self._ind = None  # the active vertex\n\n        canvas.mpl_connect('draw_event', self.on_draw)\n        canvas.mpl_connect('button_press_event', self.on_button_press)\n        canvas.mpl_connect('key_press_event', self.on_key_press)\n        canvas.mpl_connect('button_release_event', self.on_button_release)\n        canvas.mpl_connect('motion_notify_event', self.on_mouse_move)\n        self.canvas = canvas\n\n    def get_ind_under_point(self, event):\n        \"\"\"\n        Return the index of the point closest to the event position or *None*\n        if no point is within ``self.epsilon`` to the event position.\n        \"\"\"\n        xy = self.pathpatch.get_path().vertices\n        xyt = self.pathpatch.get_transform().transform(xy)  # to display coords\n        xt, yt = xyt[:, 0], xyt[:, 1]\n        d = np.sqrt((xt - event.x)**2 + (yt - event.y)**2)\n        ind = d.argmin()\n        return ind if d[ind] < self.epsilon else None\n\n    def on_draw(self, event):\n        \"\"\"Callback for draws.\"\"\"\n        self.background = self.canvas.copy_from_bbox(self.ax.bbox)\n        self.ax.draw_artist(self.pathpatch)"}]},{"title":"Create the Path Interactor","body":["In this step, we create an instance of the PathInteractor class, passing in the PathPatch object we created earlier."],"code":[{"lang":"python","text":"interactor = PathInteractor(patch)"}]},{"title":"Set Plot Properties","body":["In this step, we set the title and axis limits for the plot."],"code":[{"lang":"python","text":"ax.set_title('drag vertices to update path')\nax.set_xlim(-3, 4)\nax.set_ylim(-3, 4)"}]},{"title":"Show the Plot","body":["In this step, we show the plot on the screen."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-pathpatch-objects":{"intro":"Matplotlib is a Python library that allows the user to create different types of charts and graphs. It is used in data visualization and data analysis. In this lab, we will learn how to create a PathPatch object using Matplotlib's API.","steps":[{"title":"Import Libraries","body":["We need to import the required libraries for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath"}]},{"title":"Define Path Data","body":["We define the path data in this step. Path data is a sequence of tuples that specify the vertices and codes of the path. We use the mpath.Path class to create a Path object from this data."],"code":[{"lang":"python","text":"Path = mpath.Path\npath_data = [\n    (Path.MOVETO, (1.58, -2.57)),\n    (Path.CURVE4, (0.35, -1.1)),\n    (Path.CURVE4, (-1.75, 2.0)),\n    (Path.CURVE4, (0.375, 2.0)),\n    (Path.LINETO, (0.85, 1.15)),\n    (Path.CURVE4, (2.2, 3.2)),\n    (Path.CURVE4, (3, 0.05)),\n    (Path.CURVE4, (2.0, -0.5)),\n    (Path.CLOSEPOLY, (1.58, -2.57)),\n    ]\ncodes, verts = zip(*path_data)\npath = mpath.Path(verts, codes)"}]},{"title":"Create PathPatch Object","body":["In this step, we create a PathPatch object using the path object that we created in the previous step. This object is used to fill the area enclosed by the path. We can also set the color and transparency of the patch."],"code":[{"lang":"python","text":"patch = mpatches.PathPatch(path, facecolor='r', alpha=0.5)"}]},{"title":"Add PathPatch to Plot","body":["Now, we add the patch object to the plot using the add_patch method of the axes object."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.add_patch(patch)"}]},{"title":"Plot Control Points and Connecting Lines","body":["Plot Control Points and Connecting Lines","In this step, we plot the control points and connecting lines of the path using the plot method of the axes object."],"code":[{"lang":"python","text":"x, y = zip(*path.vertices)\nline, = ax.plot(x, y, 'go-')"}]},{"title":"Customize Plot","body":["Finally, we customize the plot by adding a grid and equalizing the axes."],"code":[{"lang":"python","text":"ax.grid()\nax.axis('equal')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.grid()\nax.axis('equal')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-path-effects-tutorial":{"intro":"In this lab, you will learn how to use path effects in Matplotlib to add special effects to your plots. Path effects allow you to add custom strokes, shadows, and other visual effects to your text and plot elements.","steps":[{"title":"Import Libraries and Prepare Data","body":["Import Libraries and Prepare Data","First, we need to import the necessary libraries and prepare some data to plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Prepare data\narr = np.arange(25).reshape((5, 5))"}]},{"title":"Add Stroke Effect to Text","body":["We can add a stroke effect to text using the withStroke path effect. In this example, we will add a stroke effect to the text annotation in the plot."],"code":[{"lang":"python","text":"# Create plot and add text annotation with stroke effect\nfig, ax = plt.subplots()\nax.imshow(arr)\ntxt = ax.annotate(\"test\", (1., 1.), (0., 0),\n                   arrowprops=dict(arrowstyle=\"->\",\n                                   connectionstyle=\"angle3\", lw=2),\n                   size=20, ha=\"center\",\n                   path_effects=[patheffects.withStroke(linewidth=3,\n                                                        foreground=\"w\")])\ntxt.arrow_patch.set_path_effects([\n    patheffects.Stroke(linewidth=5, foreground=\"w\"),\n    patheffects.Normal()])\n\n# Add grid with stroke effect\npe = [patheffects.withStroke(linewidth=3,\n                             foreground=\"w\")]\nax.grid(True, linestyle=\"-\", path_effects=pe)\n\nplt.show()"}]},{"title":"Add Stroke Effect to Contour Lines","body":["Add Stroke Effect to Contour Lines","We can also add stroke effects to contour lines and their labels using the withStroke path effect."],"code":[{"lang":"python","text":"# Create plot and add contour lines with stroke effect\nfig, ax = plt.subplots()\nax.imshow(arr)\ncntr = ax.contour(arr, colors=\"k\")\n\nplt.setp(cntr.collections, path_effects=[\n    patheffects.withStroke(linewidth=3, foreground=\"w\")])\n\nclbls = ax.clabel(cntr, fmt=\"%2.0f\", use_clabeltext=True)\nplt.setp(clbls, path_effects=[\n    patheffects.withStroke(linewidth=3, foreground=\"w\")])\n\nplt.show()"}]},{"title":"Add Shadow Effect to Legend","body":["We can add a shadow effect to a legend using the withSimplePatchShadow path effect."],"code":[{"lang":"python","text":"# Create plot and add shadow effect to legend\nfig, ax = plt.subplots()\np1, = ax.plot([0, 1], [0, 1])\nleg = ax.legend([p1], [\"Line 1\"], fancybox=True, loc='upper left')\nleg.legendPatch.set_path_effects([patheffects.withSimplePatchShadow()])\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create plot and add shadow effect to legend\nfig, ax = plt.subplots()\np1, = ax.plot([0, 1], [0, 1])\nleg = ax.legend([p1], [\"Line 1\"], fancybox=True, loc='upper left')\nleg.legendPatch.set_path_effects([patheffects.withSimplePatchShadow()])\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-drawing-flat-objects-in-3d-plot":{"intro":"Matplotlib is a popular data visualization library in Python. It provides a wide range of functions to create different types of plots and charts. One of the features of Matplotlib is the ability to draw flat objects in 3D plots. This lab will guide you through the process of drawing flat objects in 3D plots using Matplotlib.","steps":[{"title":"Import Required Libraries","body":["We will start by importing the required libraries, which are Matplotlib, NumPy, and mpl_toolkits.mplot3d.art3d."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport mpl_toolkits.mplot3d.art3d as art3d"}]},{"title":"Create a 3D Plot","body":["We will create a 3D plot using the add_subplot function of Matplotlib. The projection parameter is set to '3d' to create a 3D plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='3d')"}]},{"title":"Draw a Circle on the Wall","body":["We will draw a circle on the x=0 'wall' of the 3D plot using the Circle and pathpatch_2d_to_3d functions of Matplotlib."],"code":[{"lang":"python","text":"p = Circle((5, 5), 3)\nax.add_patch(p)\nart3d.pathpatch_2d_to_3d(p, z=0, zdir=\"x\")"}]},{"title":"Label the Axes","body":["We will manually label the axes using the text3d function. The function takes the position of the text, the text to display, the axis to be treated as the third dimension, and other parameters."],"code":[{"lang":"python","text":"def text3d(ax, xyz, s, zdir=\"z\", size=None, angle=0, usetex=False, **kwargs):\n    \"\"\"\n    Plots the string *s* on the axes *ax*, with position *xyz*, size *size*,\n    and rotation angle *angle*. *zdir* gives the axis which is to be treated as\n    the third dimension. *usetex* is a boolean indicating whether the string\n    should be run through a LaTeX subprocess or not.  Any additional keyword\n    arguments are forwarded to `.transform_path`.\n\n    Note: zdir affects the interpretation of xyz.\n    \"\"\"\n    x, y, z = xyz\n    if zdir == \"y\":\n        xy1, z1 = (x, z), y\n    elif zdir == \"x\":\n        xy1, z1 = (y, z), x\n    else:\n        xy1, z1 = (x, y), z\n\n    text_path = TextPath((0, 0), s, size=size, usetex=usetex)\n    trans = Affine2D().rotate(angle).translate(xy1[0], xy1[1])\n\n    p1 = PathPatch(trans.transform_path(text_path), **kwargs)\n    ax.add_patch(p1)\n    art3d.pathpatch_2d_to_3d(p1, z=z1, zdir=zdir)\n\n\ntext3d(ax, (4, -2, 0), \"X-axis\", zdir=\"z\", size=.5, usetex=False,\n       ec=\"none\", fc=\"k\")\ntext3d(ax, (12, 4, 0), \"Y-axis\", zdir=\"z\", size=.5, usetex=False,\n       angle=np.pi / 2, ec=\"none\", fc=\"k\")\ntext3d(ax, (12, 10, 4), \"Z-axis\", zdir=\"y\", size=.5, usetex=False,\n       angle=np.pi / 2, ec=\"none\", fc=\"k\")"}]},{"title":"Write a Latex Formula on the Floor","body":["Write a Latex Formula on the Floor","We will write a Latex formula on the z=0 'floor' of the 3D plot using the text3d function."],"code":[{"lang":"python","text":"text3d(ax, (1, 5, 0),\n       r\"$\\displaystyle G_{\\mu\\nu} + \\Lambda g_{\\mu\\nu} = \"\n       r\"\\frac{8\\pi G}{c^4} T_{\\mu\\nu}  $\",\n       zdir=\"z\", size=1, usetex=True,\n       ec=\"none\", fc=\"k\")"}]},{"title":"Set Limits and Show Plot","body":["We will set the limits of the x, y, and z axes using the set_xlim, set_ylim, and set_zlim functions of Matplotlib. Finally, we will show the 3D plot using the show function of Matplotlib."],"code":[{"lang":"python","text":"ax.set_xlim(0, 10)\nax.set_ylim(0, 10)\nax.set_zlim(0, 10)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set_xlim(0, 10)\nax.set_ylim(0, 10)\nax.set_zlim(0, 10)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-matplotlib-animations":{"intro":"In this lab, you will learn how to create an animation with Matplotlib. Specifically, you will learn how to pause and resume an animation using the Animation.pause() and Animation.resume() methods.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries to create an animation with Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation"}]},{"title":"Define the Animation","body":["In this step, we will define the animation that we want to create. We will create an animation that displays a normal distribution that moves to the right with each frame."],"code":[{"lang":"python","text":"class PauseAnimation:\n    def __init__(self):\n        # Create the figure and axis\n        fig, ax = plt.subplots()\n        ax.set_title('Click to pause/resume the animation')\n\n        # Create the x-axis values\n        x = np.linspace(-0.1, 0.1, 1000)\n\n        # Start with a normal distribution\n        self.n0 = (1.0 / ((4 * np.pi * 2e-4 * 0.1) ** 0.5)\n                   * np.exp(-x ** 2 / (4 * 2e-4 * 0.1)))\n\n        # Create the plot\n        self.p, = ax.plot(x, self.n0)\n\n        # Create the animation\n        self.animation = animation.FuncAnimation(\n            fig, self.update, frames=200, interval=50, blit=True)\n\n        # Set the animation as unpaused\n        self.paused = False\n\n        # Add a button press event to toggle pause\n        fig.canvas.mpl_connect('button_press_event', self.toggle_pause)\n\n    def toggle_pause(self, *args, **kwargs):\n        # Toggle between paused and unpaused\n        if self.paused:\n            self.animation.resume()\n        else:\n            self.animation.pause()\n        self.paused = not self.paused\n\n    def update(self, i):\n        # Update the normal distribution\n        self.n0 += i / 100 % 5\n        self.p.set_ydata(self.n0 % 20)\n        return (self.p,)"}]},{"title":"Create the Animation Object","body":["In this step, we will create an object of the PauseAnimation class that we defined in step 2."],"code":[{"lang":"python","text":"pa = PauseAnimation()"}]},{"title":"Show the Animation","body":["In this step, we will show the animation that we created in step 2."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-pcolormesh-grids-and-shading":{"intro":"Matplotlib is a data visualization library for Python. It provides a variety of tools for creating static, animated, and interactive visualizations in Python. In this lab, we will learn how to use pcolormesh and pcolor functions in Matplotlib to visualize 2D grids.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries, Matplotlib and NumPy, by running the following code block:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data for Visualization","body":["Next, we will create a 2D grid that we will use for visualization. We can create a grid using the meshgrid function in NumPy. The meshgrid function creates a grid of points given two vectors, x and y, which represent the coordinates of the grid points. We will create a grid of 5x5 points using the following code block:"],"code":[{"lang":"python","text":"nrows = 5\nncols = 5\nx = np.arange(ncols + 1)\ny = np.arange(nrows + 1)\nX, Y = np.meshgrid(x, y)\nZ = X + Y"}]},{"title":"Flat Shading","body":["The pcolormesh function in Matplotlib can visualize 2D grids. The grid specification with the least assumptions is shading='flat' and if the grid is one larger than the data in each dimension, i.e., has shape (M+1, N+1). In that case, X and Y specify the corners of quadrilaterals that are colored with the values in Z. We can visualize the grid using the following code block:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pcolormesh(X, Y, Z, shading='flat', cmap='viridis')\nax.set_title('Flat Shading')\nplt.show()"}]},{"title":"Flat Shading, Same Shape Grid","body":["If the grid is the same shape as the data in each dimension, we cannot use shading='flat'. Historically, Matplotlib silently dropped the last row and column of Z in this case, to match Matlab's behavior. If this behavior is still desired, simply drop the last row and column manually. We can visualize the grid using the following code block:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pcolormesh(x, y, Z[:-1, :-1], shading='flat', cmap='viridis')\nax.set_title('Flat Shading, Same Shape Grid')\nplt.show()"}]},{"title":"Nearest Shading, Same Shape Grid","body":["Nearest Shading, Same Shape Grid","Usually, dropping a row and column of data is not what the user means when they make X, Y, and Z all the same shape. For this case, Matplotlib allows shading='nearest' and centers the colored quadrilaterals on the grid points. If a grid that is not the correct shape is passed with shading='nearest', an error is raised. We can visualize the grid using the following code block:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pcolormesh(X, Y, Z, shading='nearest', cmap='viridis')\nax.set_title('Nearest Shading, Same Shape Grid')\nplt.show()"}]},{"title":"Auto Shading","body":["It's possible that the user would like the code to automatically choose which to use, in this case, shading='auto' will decide whether to use flat or nearest shading based on the shapes of X, Y, and Z. We can visualize the grid using the following code block:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pcolormesh(x, y, Z, shading='auto', cmap='viridis')\nax.set_title('Auto Shading')\nplt.show()"}]},{"title":"Gouraud Shading","body":["Gouraud shading can also be specified, where the color in the quadrilaterals is linearly interpolated between the grid points. The shapes of X, Y, Z must be the same. We can visualize the grid using the following code block:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.pcolormesh(X, Y, Z, shading='gouraud', cmap='viridis')\nax.set_title('Gouraud Shading')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.pcolormesh(X, Y, Z, shading='gouraud', cmap='viridis')\nax.set_title('Gouraud Shading')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-2d-image-plotting-with-pcolormesh":{"intro":"In this tutorial, we will learn how to use the pcolormesh function in the Matplotlib library to generate 2D image-style plots. We will cover the basic usage of pcolormesh, non-rectilinear pcolormesh, centered coordinates, and making levels using norms.","steps":[{"title":"Basic pcolormesh","body":["We usually specify a pcolormesh by defining the edge of quadrilaterals and the value of the quadrilateral. Note that here _x_ and _y_ each have one extra element than Z in the respective dimension."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(19680801)\nZ = np.random.rand(6, 10)\nx = np.arange(-0.5, 10, 1)  # len = 11\ny = np.arange(4.5, 11, 1)  # len = 7\n\nfig, ax = plt.subplots()\nax.pcolormesh(x, y, Z)"}]},{"title":"Non-rectilinear pcolormesh","body":["Note that we can also specify matrices for _X_ and _Y_ and have non-rectilinear quadrilaterals."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(19680801)\nZ = np.random.rand(6, 10)\nx = np.arange(-0.5, 10, 1)  # len = 11\ny = np.arange(4.5, 11, 1)  # len = 7\nX, Y = np.meshgrid(x, y)\nX = X + 0.2 * Y  # tilt the coordinates.\nY = Y + 0.3 * X\n\nfig, ax = plt.subplots()\nax.pcolormesh(X, Y, Z)"}]},{"title":"Centered coordinates","body":["Often a user wants to pass _X_ and _Y_ with the same sizes as _Z_ to .axes.Axes.pcolormesh. This is also allowed if shading='auto' is passed (default set by :rc:pcolor.shading). Pre Matplotlib 3.3, shading='flat' would drop the last column and row of _Z_, but now gives an error. If this is really what you want, then simply drop the last row and column of Z manually:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(19680801)\nZ = np.random.rand(6, 10)\nx = np.arange(10)  # len = 10\ny = np.arange(6)  # len = 6\nX, Y = np.meshgrid(x, y)\n\nfig, axs = plt.subplots(2, 1, sharex=True, sharey=True)\naxs[0].pcolormesh(X, Y, Z, vmin=np.min(Z), vmax=np.max(Z), shading='auto')\naxs[0].set_title(\"shading='auto' = 'nearest'\")\naxs[1].pcolormesh(X, Y, Z[:-1, :-1], vmin=np.min(Z), vmax=np.max(Z),\n                  shading='flat')\naxs[1].set_title(\"shading='flat'\")"}]},{"title":"Making levels using norms","body":["Shows how to combine Normalization and Colormap instances to draw \"levels\" in .axes.Axes.pcolor, .axes.Axes.pcolormesh and .axes.Axes.imshow type plots in a similar way to the levels keyword argument to contour/contourf."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.colors import BoundaryNorm\nfrom matplotlib.ticker import MaxNLocator\n\n# make these smaller to increase the resolution\ndx, dy = 0.05, 0.05\n\n# generate 2 2d grids for the x & y bounds\ny, x = np.mgrid[slice(1, 5 + dy, dy),\n                slice(1, 5 + dx, dx)]\n\nz = np.sin(x)**10 + np.cos(10 + y*x) * np.cos(x)\n\n# x and y are bounds, so z should be the value *inside* those bounds.\n# Therefore, remove the last value from the z array.\nz = z[:-1, :-1]\nlevels = MaxNLocator(nbins=15).tick_values(z.min(), z.max())\n\n\n# pick the desired colormap, sensible levels, and define a normalization\n# instance which takes data values and translates those into levels.\ncmap = plt.colormaps['PiYG']\nnorm = BoundaryNorm(levels, ncolors=cmap.N, clip=True)\n\nfig, (ax0, ax1) = plt.subplots(nrows=2)\n\nim = ax0.pcolormesh(x, y, z, cmap=cmap, norm=norm)\nfig.colorbar(im, ax=ax0)\nax0.set_title('pcolormesh with levels')\n\n\n# contours are *point* based plots, so convert our bound into point\n# centers\ncf = ax1.contourf(x[:-1, :-1] + dx/2.,\n                  y[:-1, :-1] + dy/2., z, levels=levels,\n                  cmap=cmap)\nfig.colorbar(cf, ax=ax1)\nax1.set_title('contourf with levels')\n\n# adjust spacing between subplots so `ax1` title and `ax0` tick labels\n# don't overlap\nfig.tight_layout()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.colors import BoundaryNorm\nfrom matplotlib.ticker import MaxNLocator\n\n# make these smaller to increase the resolution\ndx, dy = 0.05, 0.05\n\n# generate 2 2d grids for the x & y bounds\ny, x = np.mgrid[slice(1, 5 + dy, dy),\n                slice(1, 5 + dx, dx)]\n\nz = np.sin(x)**10 + np.cos(10 + y*x) * np.cos(x)\n\n# x and y are bounds, so z should be the value *inside* those bounds.\n# Therefore, remove the last value from the z array.\nz = z[:-1, :-1]\nlevels = MaxNLocator(nbins=15).tick_values(z.min(), z.max())\n\n\n# pick the desired colormap, sensible levels, and define a normalization\n# instance which takes data values and translates those into levels.\ncmap = plt.colormaps['PiYG']\nnorm = BoundaryNorm(levels, ncolors=cmap.N, clip=True)\n\nfig, (ax0, ax1) = plt.subplots(nrows=2)\n\nim = ax0.pcolormesh(x, y, z, cmap=cmap, norm=norm)\nfig.colorbar(im, ax=ax0)\nax0.set_title('pcolormesh with levels')\n\n\n# contours are *point* based plots, so convert our bound into point\n# centers\ncf = ax1.contourf(x[:-1, :-1] + dx/2.,\n                  y[:-1, :-1] + dy/2., z, levels=levels,\n                  cmap=cmap)\nfig.colorbar(cf, ax=ax1)\nax1.set_title('contourf with levels')\n\n# adjust spacing between subplots so `ax1` title and `ax0` tick labels\n# don't overlap\nfig.tight_layout()\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-pgf-font-customization":{"intro":"Matplotlib is a data visualization library that allows you to create a variety of visualizations in Python. One important aspect of creating visualizations is selecting the appropriate font for your text. In this tutorial, we will learn how to use PGF fonts in Matplotlib.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries for this tutorial. We will be using matplotlib.pyplot to create our visualization."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Set the font family","body":["We will set the font family to \"serif\" using the font.family parameter. Additionally, we will set the font.serif parameter to an empty list to use the default LaTeX serif font."],"code":[{"lang":"python","text":"plt.rcParams.update({\n    \"font.family\": \"serif\",\n    \"font.serif\": [],\n})"}]},{"title":"Set the cursive fonts","body":["We will set the cursive fonts using the font.cursive parameter. In this example, we will use \"Comic Neue\" and \"Comic Sans MS\"."],"code":[{"lang":"python","text":"plt.rcParams.update({\n    \"font.cursive\": [\"Comic Neue\", \"Comic Sans MS\"],\n})"}]},{"title":"Create the plot","body":["Next, we will create a simple line plot using the ax.plot() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(4.5, 2.5))\n\nax.plot(range(5))"}]},{"title":"Add text to the plot","body":["We will add text to the plot using the ax.text() function. We will add text to four different locations on the plot, each with a different font family: serif, monospace, sans-serif, and cursive."],"code":[{"lang":"python","text":"ax.text(0.5, 3., \"serif\")\nax.text(0.5, 2., \"monospace\", family=\"monospace\")\nax.text(2.5, 2., \"sans-serif\", family=\"DejaVu Sans\")\nax.text(2.5, 1., \"comic\", family=\"cursive\")"}]},{"title":"Set the x-label","body":["We will set the x-label using the ax.set_xlabel() function. We will use the Greek letter mu as an example."],"code":[{"lang":"python","text":"ax.set_xlabel(\"µ is not $\\\\mu$\")"}]},{"title":"Save the plot","body":["Finally, we will save the plot as a PDF and PNG file using the fig.savefig() function."],"code":[{"lang":"python","text":"fig.tight_layout(pad=.5)\n\nfig.savefig(\"pgf_fonts.pdf\")\nfig.savefig(\"pgf_fonts.png\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.tight_layout(pad=.5)\n\nfig.savefig(\"pgf_fonts.pdf\")\nfig.savefig(\"pgf_fonts.png\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-pgf-preamble-sgskip":{"intro":"In this lab, you will learn how to use Python's Matplotlib library to create plots and graphs. Matplotlib is a powerful library that allows you to create a wide range of visualizations, from simple line plots to complex heatmaps. By the end of this lab, you will have a good understanding of how to use Matplotlib to create basic visualizations.","steps":[{"title":"Install Matplotlib","body":[],"code":[{"lang":"text","text":"pip install matplotlib"}]},{"title":"Import Matplotlib","body":["Once you have installed Matplotlib, you can import it in your Python code. To import Matplotlib, add the following line to the top of your Python script:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Simple Line Plot","body":["Let's start by creating a simple line plot. In this example, we will plot the sine and cosine functions over the interval [0, 2π]."],"code":[{"lang":"python","text":"import numpy as np\n\nx = np.linspace(0, 2*np.pi, 100)\ny1 = np.sin(x)\ny2 = np.cos(x)\n\nplt.plot(x, y1, label='sin')\nplt.plot(x, y2, label='cos')\nplt.xlabel('x')\nplt.ylabel('y')\nplt.title('Sine and Cosine Functions')\nplt.legend()\nplt.show()"}]},{"title":"Customize the Plot","body":["You can customize the plot by changing the colors, line styles, and markers. Here's an example:"],"code":[{"lang":"python","text":"plt.plot(x, y1, 'r--', label='sin')\nplt.plot(x, y2, 'g:', label='cos')\nplt.xlabel('x')\nplt.ylabel('y')\nplt.title('Sine and Cosine Functions')\nplt.legend()\nplt.show()"}]},{"title":"Create a Scatter Plot","body":["In addition to line plots, Matplotlib can also create scatter plots. Here's an example:"],"code":[{"lang":"python","text":"x = np.random.rand(50)\ny = np.random.rand(50)\ncolors = np.random.rand(50)\nsizes = 500 * np.random.rand(50)\n\nplt.scatter(x, y, c=colors, s=sizes)\nplt.xlabel('x')\nplt.ylabel('y')\nplt.title('Scatter Plot')\nplt.show()"}]},{"title":"Create a Bar Plot","body":["Matplotlib can also create bar plots. Here's an example:"],"code":[{"lang":"python","text":"x = ['A', 'B', 'C', 'D', 'E']\ny = [3, 7, 1, 9, 4]\n\nplt.bar(x, y)\nplt.xlabel('Category')\nplt.ylabel('Value')\nplt.title('Bar Plot')\nplt.show()"}]}],"commands":["pip install matplotlib"],"reference":[{"path":"reference.py","text":"x = ['A', 'B', 'C', 'D', 'E']\ny = [3, 7, 1, 9, 4]\n\nplt.bar(x, y)\nplt.xlabel('Category')\nplt.ylabel('Value')\nplt.title('Bar Plot')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-plot-with-custom-fonts":{"intro":"In this lab, you will learn how to create a plot with custom fonts using the Python Matplotlib library. You will be introduced to the pgf.texsystem parameter that allows you to use LaTeX to customize the font family of your plot.","steps":[{"title":"Import Matplotlib and Set the pgf.texsystem Parameter","body":["Import Matplotlib and Set the pgf.texsystem Parameter","First, you need to import the Matplotlib library and set the pgf.texsystem parameter to pdflatex. This parameter allows you to use LaTeX to customize the font family of your plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams.update({\n    \"pgf.texsystem\": \"pdflatex\",\n})"}]},{"title":"Define the Font Family","body":["Next, you need to define the font family that you want to use in your plot. In this example, we will use the cmbright font family."],"code":[{"lang":"python","text":"plt.rcParams.update({\n    \"pgf.texsystem\": \"pdflatex\",\n    \"pgf.preamble\": \"\\n\".join([\n         r\"\\usepackage[utf8x]{inputenc}\",\n         r\"\\usepackage[T1]{fontenc}\",\n         r\"\\usepackage{cmbright}\",\n    ]),\n})"}]},{"title":"Create the Plot","body":["Now, you can create your plot using the plt.subplots() function. In this example, we will create a simple line plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(4.5, 2.5))\n\nax.plot(range(5))"}]},{"title":"Add Text to the Plot","body":["You can add text to your plot using the ax.text() function. In this example, we will add text with different font families."],"code":[{"lang":"python","text":"ax.text(0.5, 3., \"serif\", family=\"serif\")\nax.text(0.5, 2., \"monospace\", family=\"monospace\")\nax.text(2.5, 2., \"sans-serif\", family=\"sans-serif\")\nax.set_xlabel(r\"µ is not $\\mu$\")"}]},{"title":"Adjust the Layout and Save the Plot","body":["Adjust the Layout and Save the Plot","Finally, you can adjust the layout of your plot and save it to a file using the fig.tight_layout() and fig.savefig() functions, respectively."],"code":[{"lang":"python","text":"fig.tight_layout(pad=.5)\n\nfig.savefig(\"pgf_texsystem.pdf\")\nfig.savefig(\"pgf_texsystem.png\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.tight_layout(pad=.5)\n\nfig.savefig(\"pgf_texsystem.pdf\")\nfig.savefig(\"pgf_texsystem.png\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-interactive-matplotlib-visualization-techniq":{"intro":"This lab aims to introduce you to the concept of picking in Matplotlib. The ability to pick artists is a powerful tool that can be used to build interactive visualizations that respond to user actions. We will cover simple picking, picking with custom hit test functions, picking on a scatter plot, and picking images.","steps":[{"title":"Simple Picking, Lines, Rectangles, and Text","body":["Simple Picking, Lines, Rectangles, and Text","We will start by enabling simple picking by setting the \"picker\" property of an artist. This will enable the artist to fire a pick event if the mouse event is over the artist. We will create a simple plot containing a line, rectangle, and text, and enable picking on each of these artists."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(2, 1)\nax1.set_title('click on points, rectangles or text', picker=True)\nax1.set_ylabel('ylabel', picker=True, bbox=dict(facecolor='red'))\nline, = ax1.plot(rand(100), 'o', picker=True, pickradius=5)\n\n# Pick the rectangle.\nax2.bar(range(10), rand(10), picker=True)\nfor label in ax2.get_xticklabels():  # Make the xtick labels pickable.\n    label.set_picker(True)"}]},{"title":"Creating a Custom Hit Test Function","body":["Creating a Custom Hit Test Function","In this step, we will define a custom picker by setting picker to a callable function. The function will determine whether the artist is hit by the mouse event. If the mouse event is over the artist, we will return hit=True and props is a dictionary of properties you want added to the .PickEvent attributes."],"code":[{"lang":"python","text":"def line_picker(line, mouseevent):\n    \"\"\"\n    Find the points within a certain distance from the mouseclick in\n    data coords and attach some extra attributes, pickx and picky\n    which are the data points that were picked.\n    \"\"\"\n    if mouseevent.xdata is None:\n        return False, dict()\n    xdata = line.get_xdata()\n    ydata = line.get_ydata()\n    maxd = 0.05\n    d = np.sqrt(\n        (xdata - mouseevent.xdata)**2 + (ydata - mouseevent.ydata)**2)\n\n    ind, = np.nonzero(d <= maxd)\n    if len(ind):\n        pickx = xdata[ind]\n        picky = ydata[ind]\n        props = dict(ind=ind, pickx=pickx, picky=picky)\n        return True, props\n    else:\n        return False, dict()\n\n\ndef onpick2(event):\n    print('onpick2 line:', event.pickx, event.picky)\n\n\nfig, ax = plt.subplots()\nax.set_title('custom picker for line data')\nline, = ax.plot(rand(100), rand(100), 'o', picker=line_picker)\nfig.canvas.mpl_connect('pick_event', onpick2)"}]},{"title":"Picking on a Scatter Plot","body":["A scatter plot is backed by a ~matplotlib.collections.PathCollection. We will create a scatter plot and enable picking."],"code":[{"lang":"python","text":"x, y, c, s = rand(4, 100)\n\n\ndef onpick3(event):\n    ind = event.ind\n    print('onpick3 scatter:', ind, x[ind], y[ind])\n\n\nfig, ax = plt.subplots()\nax.scatter(x, y, 100*s, c, picker=True)\nfig.canvas.mpl_connect('pick_event', onpick3)"}]},{"title":"Picking Images","body":["Images plotted using .Axes.imshow are ~matplotlib.image.AxesImage objects. We will create a figure with multiple images and enable picking."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.imshow(rand(10, 5), extent=(1, 2, 1, 2), picker=True)\nax.imshow(rand(5, 10), extent=(3, 4, 1, 2), picker=True)\nax.imshow(rand(20, 25), extent=(1, 2, 3, 4), picker=True)\nax.imshow(rand(30, 12), extent=(3, 4, 3, 4), picker=True)\nax.set(xlim=(0, 5), ylim=(0, 5))\n\n\ndef onpick4(event):\n    artist = event.artist\n    if isinstance(artist, AxesImage):\n        im = artist\n        A = im.get_array()\n        print('onpick4 image', A.shape)\n\n\nfig.canvas.mpl_connect('pick_event', onpick4)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.imshow(rand(10, 5), extent=(1, 2, 1, 2), picker=True)\nax.imshow(rand(5, 10), extent=(3, 4, 1, 2), picker=True)\nax.imshow(rand(20, 25), extent=(1, 2, 3, 4), picker=True)\nax.imshow(rand(30, 12), extent=(3, 4, 3, 4), picker=True)\nax.set(xlim=(0, 5), ylim=(0, 5))\n\n\ndef onpick4(event):\n    artist = event.artist\n    if isinstance(artist, AxesImage):\n        im = artist\n        A = im.get_array()\n        print('onpick4 image', A.shape)\n\n\nfig.canvas.mpl_connect('pick_event', onpick4)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-data-visualization-with-python":{"intro":"In this lab, we will use Python's Matplotlib library to compute the mean (mu) and standard deviation (sigma) of 100 data sets and plot mu vs. sigma. We will also add interactivity to the plot so that when you click on one of the (mu, sigma) points, the raw data from the dataset that generated this point will be plotted.","steps":[{"title":"Generate Random Data","body":["First, we need to generate 100 random datasets, each containing 1000 random numbers between 0 and 1. We will use numpy's random module to generate the random data."],"code":[{"lang":"python","text":"import numpy as np\n\nnp.random.seed(19680801)\n\nX = np.random.rand(100, 1000)"}]},{"title":"Compute Mean and Standard Deviation","body":["Compute Mean and Standard Deviation","Next, we will compute the mean and standard deviation of each of the 100 datasets. We will use numpy's mean and std functions to compute these values."],"code":[{"lang":"python","text":"xs = np.mean(X, axis=1)\nys = np.std(X, axis=1)"}]},{"title":"Plot the Data","body":["Now, we will plot mu vs. sigma using Matplotlib's pyplot module. We will create a scatter plot using the computed values for mu and sigma. We will also add interactivity to the plot by setting the picker parameter to True."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, ax = plt.subplots()\nax.set_title('click on point to plot time series')\nline, = ax.plot(xs, ys, 'o', picker=True, pickradius=5)"}]},{"title":"Add Interactivity","body":[],"code":[{"lang":"python","text":"def onpick(event):\n\n    if event.artist != line:\n        return\n\n    N = len(event.ind)\n    if not N:\n        return\n\n    figi, axs = plt.subplots(N, squeeze=False)\n    for ax, dataind in zip(axs.flat, event.ind):\n        ax.plot(X[dataind])\n        ax.text(.05, .9, f'mu={xs[dataind]:1.3f}\\nsigma={ys[dataind]:1.3f}',\n                transform=ax.transAxes, va='top')\n        ax.set_ylim(-0.5, 1.5)\n    figi.show()\n\n\nfig.canvas.mpl_connect('pick_event', onpick)"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-pie-and-donut-chart":{"intro":"In this lab, we will create a pie and a donut chart using Python's Matplotlib library. We will learn how to label them with a legend as well as with annotations.","steps":[{"title":"Import necessary libraries and create a figure with subplots","body":["Import necessary libraries and create a figure with subplots","We start by importing the necessary libraries and creating a figure with subplots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfig, ax = plt.subplots(figsize=(6, 3), subplot_kw=dict(aspect=\"equal\"))"}]},{"title":"Create a Pie Chart","body":["We will now create a pie chart for a recipe that has four ingredients: flour, sugar, butter, and berries."],"code":[{"lang":"python","text":"recipe = [\"375 g flour\",\n          \"75 g sugar\",\n          \"250 g butter\",\n          \"300 g berries\"]\n\ndata = [float(x.split()[0]) for x in recipe]\ningredients = [x.split()[-1] for x in recipe]\n\ndef func(pct, allvals):\n    absolute = int(np.round(pct/100.*np.sum(allvals)))\n    return f\"{pct:.1f}%\\n({absolute:d} g)\"\n\nwedges, texts, autotexts = ax.pie(data, autopct=lambda pct: func(pct, data),\n                                  textprops=dict(color=\"w\"))\n\nax.legend(wedges, ingredients,\n          title=\"Ingredients\",\n          loc=\"center left\",\n          bbox_to_anchor=(1, 0, 0.5, 1))\n\nplt.setp(autotexts, size=8, weight=\"bold\")\n\nax.set_title(\"Matplotlib bakery: A pie\")\n\nplt.show()"}]},{"title":"Create a Donut Chart","body":["We will now create a donut chart for a recipe that has six ingredients: flour, sugar, egg, butter, milk, and yeast."],"code":[{"lang":"python","text":"recipe = [\"225 g flour\",\n          \"90 g sugar\",\n          \"1 egg\",\n          \"60 g butter\",\n          \"100 ml milk\",\n          \"1/2 package of yeast\"]\n\ndata = [225, 90, 50, 60, 100, 5]\n\nwedges, texts = ax.pie(data, wedgeprops=dict(width=0.5), startangle=-40)\n\nbbox_props = dict(boxstyle=\"square,pad=0.3\", fc=\"w\", ec=\"k\", lw=0.72)\nkw = dict(arrowprops=dict(arrowstyle=\"-\"),\n          bbox=bbox_props, zorder=0, va=\"center\")\n\nfor i, p in enumerate(wedges):\n    ang = (p.theta2 - p.theta1)/2. + p.theta1\n    y = np.sin(np.deg2rad(ang))\n    x = np.cos(np.deg2rad(ang))\n    horizontalalignment = {-1: \"right\", 1: \"left\"}[int(np.sign(x))]\n    connectionstyle = f\"angle,angleA=0,angleB={ang}\"\n    kw[\"arrowprops\"].update({\"connectionstyle\": connectionstyle})\n    ax.annotate(recipe[i], xy=(x, y), xytext=(1.35*np.sign(x), 1.4*y),\n                horizontalalignment=horizontalalignment, **kw)\n\nax.set_title(\"Matplotlib bakery: A donut\")\n\nplt.show()"}]},{"title":"Conclusion","body":["We have learned how to create a pie and a donut chart using Matplotlib, and how to label them with a legend and annotations."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
